import{_ as o,o as d,c,a0 as t}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"📜 WealthFam Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"Management/CHANGELOG.md","filePath":"Management/CHANGELOG.md"}'),a={name:"Management/CHANGELOG.md"};function i(n,e,r,s,l,u){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="📜-wealthfam-changelog" tabindex="-1">📜 WealthFam Changelog <a class="header-anchor" href="#📜-wealthfam-changelog" aria-label="Permalink to &quot;📜 WealthFam Changelog&quot;">​</a></h1><p>Archived completed work moved from <a href="./backlog.html">backlog.md</a> per <a href="./PRACTICES.html">PRACTICES.md</a> and aligned with <code>Infra/version.json</code>.</p><hr><h2 id="unreleased-—-2026-11-28" tabindex="-1">[Unreleased] — 2026-11-28 <a class="header-anchor" href="#unreleased-—-2026-11-28" aria-label="Permalink to &quot;[Unreleased] — 2026-11-28&quot;">​</a></h2><h3 id="📧-email-sync-hardening-configurable-sync-frequency-p2-d-—-backend-web-app-mobile-app-test-suite-docs" tabindex="-1">📧 Email Sync Hardening &amp; Configurable Sync Frequency (<code>P2-D</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>, <code>Docs</code>) <a class="header-anchor" href="#📧-email-sync-hardening-configurable-sync-frequency-p2-d-—-backend-web-app-mobile-app-test-suite-docs" aria-label="Permalink to &quot;📧 Email Sync Hardening &amp; Configurable Sync Frequency (`P2-D` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`, `Docs`)&quot;">​</a></h3><ul><li><strong>Email Sync Reliability &amp; Parsing Hardening (<code>Backend</code>)</strong>: <ul><li>Hardened <code>EmailSyncService</code> (<code>email_sync.py</code>) with explicit <code>30s</code> IMAP socket timeout, <code>select()</code>/<code>search()</code> status checks, <code>finally:</code> socket cleanup, and guaranteed <code>EmailSyncLog</code> error finalization so sync logs never get stuck in <code>&quot;running&quot;</code>.</li><li>Added locale-independent RFC 3501 <code>SINCE</code> formatting with 1-day boundary backoff (<code>_format_imap_since</code>), RFC 2047 decoding for both <code>Subject</code> and <code>From</code> headers, charset-aware multipart body accumulation + <code>html.unescape()</code>, UTC <code>received_at</code> normalization, SQLAlchemy 2.x <code>db.get()</code>, and statement-PDF <code>statement_queued</code> accounting (plus removing false-positive <code>&quot;subscription&quot;</code> from <code>noise_keywords</code>).</li></ul></li><li><strong>Configurable Per-Mailbox Sync Interval &amp; Zero-PII Admin Telemetry (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>EmailConfiguration.sync_interval_minutes</code> (<code>15..1440</code>, default <code>180</code>) with Alembic migration <code>p7k8l9m0n1o2_add_email_sync_interval.py</code>, updated <code>auto_sync_job</code> to tick every 15 minutes honoring each mailbox&#39;s configured interval and emitting zero-PII run summaries (mailbox/email counts + sanitized error class names, strictly excluding emails/hostnames/tenant IDs) to <code>Admin-Backend</code>, added the <strong>Sync Frequency</strong> selector &amp; card badge in Web <code>EmailSettings.vue</code>, and added a Web Dashboard configuration banner in Mobile <code>sync_settings_screen.dart</code>.</li></ul></li><li><strong>Permanent Regression Tests &amp; Docs (<code>Test-Suite</code>, <code>Docs</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/ingestion/test_p2d_email_sync_hardening.py</code> and updated <code>Docs/technical/data ingestion/email_ingestion.md</code>.</li></ul></li></ul><h3 id="🧹-ops-data-hygiene-—-14-day-permanent-log-auto-prune-admin-scheduler-telemetry-p2-c-—-backend-admin-backend-admin-web-web-app-mobile-app-website-test-suite-docs" tabindex="-1">🧹 Ops &amp; Data Hygiene — 14-Day Permanent Log Auto-Prune &amp; Admin Scheduler Telemetry (<code>P2-C</code> — <code>Backend</code>, <code>Admin-Backend</code>, <code>Admin-Web</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Website</code>, <code>Test-Suite</code>, <code>Docs</code>) <a class="header-anchor" href="#🧹-ops-data-hygiene-—-14-day-permanent-log-auto-prune-admin-scheduler-telemetry-p2-c-—-backend-admin-backend-admin-web-web-app-mobile-app-website-test-suite-docs" aria-label="Permalink to &quot;🧹 Ops &amp; Data Hygiene — 14-Day Permanent Log Auto-Prune &amp; Admin Scheduler Telemetry (`P2-C` — `Backend`, `Admin-Backend`, `Admin-Web`, `Web-App`, `Mobile-App`, `Website`, `Test-Suite`, `Docs`)&quot;">​</a></h3><ul><li><strong>Dedicated Permanent Log Purge Module (<code>Backend</code>)</strong>: <ul><li>Added <code>INGESTION_LOG_RETENTION_DAYS = 14</code> in <code>Backend/app/core/config.py</code> and created <code>Backend/app/modules/ingestion/retention_service.py</code> (<code>IngestionRetentionService.prune_old_logs</code>) to <strong>permanently hard-delete</strong> (no soft-delete) <code>email_sync_item_logs</code> → <code>email_sync_logs</code> → <code>ingestion_events</code> older than 14 days in FK-safe order without touching ledger transactions or vault documents.</li><li>Scheduled <code>daily_ingestion_log_prune</code> daily at <code>03:15 UTC</code> in <code>Backend/app/core/scheduler.py</code>.</li></ul></li><li><strong>Zero-PII Admin Scheduler Telemetry &amp; Dedicated <code>/schedulers</code> Page (<code>Backend</code>, <code>Admin-Backend</code>, <code>Admin-Web</code>)</strong>: <ul><li>Added <code>enqueue_scheduler_event</code> and <code>record_scheduler_run</code> in <code>Backend/app/core/telemetry.py</code> and wired all Backend schedulers (including <code>daily_ingestion_log_prune</code> and <code>daily_balance_drift_audit_job</code>) to report high-level counts, status, and duration to <code>Admin-Backend</code>.</li><li>Added DuckDB <code>telemetry_scheduler_runs</code> table, extended <code>POST /v1/telemetry/ingest</code> with <code>scheduler_events</code>, added <code>GET /v1/telemetry/schedulers</code>, and added the new <code>Admin-Web</code> <strong>Schedulers</strong> page (<code>SchedulersView.vue</code>, <code>/schedulers</code>).</li></ul></li><li><strong>14-Day Retention Notices &amp; Filter Caps (<code>Web-App</code>, <code>Mobile-App</code>, <code>Website</code>, <code>Docs</code>)</strong>: <ul><li>Capped review windows to 14 days and added clear 14-day permanent auto-purge notices in Web <code>IngestionsSettings.vue</code> and Mobile <code>ingestion_activity_tab.dart</code>.</li><li>Documented the 14-day retention policy on the <code>Website</code> How-To guide and updated <code>Docs/technical/architecture/ingestion.md</code> &amp; <code>system_overview.md</code>.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/ingestion/test_p2c_log_retention_and_scheduler_telemetry.py</code>.</li></ul></li></ul><h3 id="📱-mobile-gateway-deduplication-route-normalization-p2-b-—-backend-mobile-app-test-suite-docs" tabindex="-1">📱 Mobile Gateway Deduplication &amp; Route Normalization (<code>P2-B</code> — <code>Backend</code>, <code>Mobile-App</code>, <code>Test-Suite</code>, <code>Docs</code>) <a class="header-anchor" href="#📱-mobile-gateway-deduplication-route-normalization-p2-b-—-backend-mobile-app-test-suite-docs" aria-label="Permalink to &quot;📱 Mobile Gateway Deduplication &amp; Route Normalization (`P2-B` — `Backend`, `Mobile-App`, `Test-Suite`, `Docs`)&quot;">​</a></h3><ul><li><strong>Deduplicated 4 Shadowed Routes in Mobile Gateway (<code>Backend</code>)</strong>: <ul><li>Removed shadowed duplicate handlers for <code>GET /funds</code>, <code>GET /funds/{scheme_code}</code>, <code>GET /categories</code>, and <code>GET /vendor/stats</code> in <code>Backend/app/modules/mobile/api/router.py</code>.</li><li>Added dual <code>member_id</code> / <code>user_id</code> query parameter support on <code>GET /funds</code>, <code>GET /vendor/stats</code>, and <code>GET /mutual-funds/analytics/performance-timeline</code> (also forwarding <code>period</code> &amp; <code>granularity</code>), and added <code>tree: bool = True</code> to <code>GET /categories</code>.</li></ul></li><li><strong>Mobile-App Route Normalization (<code>Mobile-App</code>, <code>Docs</code>)</strong>: <ul><li>Migrated already-mirrored calls in <code>vault_service.dart</code>, <code>statement_detail_screen.dart</code>, <code>funds_repository.dart</code>, <code>categories_repository.dart</code>, <code>accounts_repository.dart</code> (FD/PF), and <code>finance_repository.dart</code> (transaction detail/update/delete) from <code>/api/v1/finance/*</code> to <code>/api/v1/mobile/*</code>, and passed <code>member_id</code> + <code>user_id</code> on <code>GET /api/v1/mobile/funds</code>.</li><li>Documented explicitly exempt shared cross-client endpoints (<code>/api/v1/ingestion/sms</code>, <code>/api/v1/auth/*</code>, <code>/api/v1/brands/*</code>, <code>/api/v1/telemetry/*</code>) in <code>Docs/Management/PRACTICES.md</code> §2.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/mobile/test_p2b_mobile_gateway_dedup.py</code> asserting zero duplicate <code>(method, path)</code> routes in the mobile gateway and dual <code>member_id</code>/<code>user_id</code> query parameter support.</li></ul></li></ul><h3 id="🖥️-web-app-timestamp-filter-account-view-fixes-p2-a-—-web-app" tabindex="-1">🖥️ Web-App Timestamp, Filter &amp; Account View Fixes (<code>P2-A</code> — <code>Web-App</code>) <a class="header-anchor" href="#🖥️-web-app-timestamp-filter-account-view-fixes-p2-a-—-web-app" aria-label="Permalink to &quot;🖥️ Web-App Timestamp, Filter &amp; Account View Fixes (`P2-A` — `Web-App`)&quot;">​</a></h3><ul><li><strong>Lossless UTC ↔ Local Transaction Edit Picker</strong>: Added <code>utcToLocalInput()</code> in <code>Web-App/src/utils/time.ts</code> and wired it into <code>useTransactionModals.ts</code> so editing and re-saving transactions no longer subtracts the local UTC offset (e.g., <code>-5h30m</code> in IST).</li><li><strong>Accurate &quot;Today&quot; Filter &amp; Family Member Filter Propagation</strong>: Fixed <code>useTransactionState.ts</code> (<code>case &#39;today&#39;</code> setting <code>end = todayLocalString()</code> instead of <code>today + 1</code>), and propagated &amp; watched <code>auth.selectedMemberId</code> across <code>stores/finance.ts</code>, <code>Dashboard.vue</code>, <code>CreditCards.vue</code>, <code>Deposits.vue</code>, and <code>ProvidentFunds.vue</code>.</li><li><strong><code>AccountDetails.vue</code> Stability &amp; UX</strong>: Defaulted <code>periodFilter</code> to <code>&#39;month&#39;</code> for non-<code>CREDIT_CARD</code> accounts so initial charts render immediately, passed <code>includeUnverified: true</code> in <code>fetchAccount()</code>, removed duplicate <code>@input=&quot;fetchTransactions&quot;</code> (which passed <code>InputEvent</code> as pagination options), and added a 300ms debounced search watcher.</li></ul><h3 id="📊-net-worth-analytics-budgets-recurring-parity-p1-e-—-backend-web-app-mobile-app-test-suite" tabindex="-1">📊 Net Worth, Analytics, Budgets &amp; Recurring Parity (<code>P1-E</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#📊-net-worth-analytics-budgets-recurring-parity-p1-e-—-backend-web-app-mobile-app-test-suite" aria-label="Permalink to &quot;📊 Net Worth, Analytics, Budgets &amp; Recurring Parity (`P1-E` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Net Worth, History Timeline &amp; Goal Asset Parity (<code>Backend</code>, <code>Web-App</code>)</strong>: <ul><li>Unified <code>CoreAnalytics.get_summary_metrics</code>, <code>HistoryAnalytics.get_net_worth_timeline</code>, and <code>InvestmentAnalytics.get_family_wealth</code> to include <code>MutualFundHolding</code> valuations, accrued FD/RD valuations via <code>FixedDepositService.valuation()</code>, and Provident Fund balances consistently; added same-day post-snapshot transaction replay in <code>HistoryAnalytics</code>.</li><li>Blocked linking <code>CREDIT_CARD</code> or <code>LOAN</code> liability accounts as goal assets in <code>InvestmentGoalService.add_asset</code> (<code>ValueError</code> → HTTP <code>400</code> in <code>routers/investment_goals.py</code>) and excluded them in Web <code>InvestmentGoals.vue</code> and <code>LinkAssetModal.vue</code>.</li><li>Fixed <code>Dashboard.vue</code> <code>% MoM</code> net-worth delta to compare against the start of the ~30-day window using <code>Math.abs(previous)</code> (avoiding sign inversion on negative net worth), and fixed negative <code>mfPortfolio.pl</code> to render in error/rose color with <code>TrendingDown</code>.</li></ul></li><li><strong>Uncategorized Spending, Soft-Deleted Accounts &amp; Role Filter Parity (<code>Backend</code>)</strong>: <ul><li>Standardized <code>outerjoin(Category)</code> across <code>CoreAnalytics</code>, <code>SpendingAnalytics</code>, <code>HistoryAnalytics</code> (<code>get_budget_history</code>, <code>get_calendar_heatmap</code>, <code>get_daily_spending_history</code>), and <code>BudgetService</code> so uncategorized debits match identically across Dashboard, Insights, and Budgets.</li><li>Enforced <code>Account.is_deleted == False</code> across Family/All analytics views, Budgets, and <code>MobileExpenseGroupService.calculate_total_spend</code>; migrated <code>MobileExpenseGroupService.delete_expense_group</code> from hard-delete to soft-delete (<code>is_deleted = True</code>, <code>deleted_at = timezone.utcnow()</code>).</li><li>Fixed <code>CHILD</code> role account exclusion filters in <code>CoreAnalytics</code> and <code>TransactionService</code> from <code>[&quot;INVESTMENT&quot;, &quot;CREDIT&quot;]</code> to <code>[&quot;INVESTMENT&quot;, &quot;CREDIT_CARD&quot;, &quot;LOAN&quot;]</code>.</li></ul></li><li><strong>Recurring Transactions Sign, Edit &amp; Forecast Window (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Standardized <code>RecurringTransaction.amount</code> as positive magnitude (<code>abs(Decimal)</code>) in <code>RecurringService.create_recurring_transaction</code> / <code>update_recurring_transaction</code>, emitted signed amounts (<code>-amt</code> for <code>DEBIT</code>, <code>+amt</code> for <code>CREDIT</code>) in <code>process_recurring_transactions</code>, and updated <code>CoreAnalytics.get_balance_forecast</code> to project all occurrences within the forecast window scoped to liquid (<code>BANK</code>/<code>WALLET</code>) accounts.</li><li>Updated Web <code>RecurringTab.vue</code> and Mobile <code>analytics_recurring_tab.dart</code> with <code>DEBIT</code>/<code>CREDIT</code> type selectors, preserved <code>type</code> &amp; <code>start_date</code>/<code>next_run_date</code> on edit, and ensured Web &quot;Add Subscription&quot; resets form state.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/finance/test_p1e_analytics_and_recurring_parity.py</code> (4 suites covering <code>P1-E.1</code>, <code>P1-E.2</code>, and <code>P1-E.3</code>).</li></ul></li></ul><h3 id="🏦-financial-instruments-accuracy-—-loans-deposits-fd-rd-pf-mutual-funds-p1-d-—-backend-web-app-mobile-app-test-suite" tabindex="-1">🏦 Financial Instruments Accuracy — Loans, Deposits (FD/RD), PF &amp; Mutual Funds (<code>P1-D</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#🏦-financial-instruments-accuracy-—-loans-deposits-fd-rd-pf-mutual-funds-p1-d-—-backend-web-app-mobile-app-test-suite" aria-label="Permalink to &quot;🏦 Financial Instruments Accuracy — Loans, Deposits (FD/RD), PF &amp; Mutual Funds (`P1-D` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Loan EMI Principal/Interest Split, Prepayment &amp; Month-End Date Clamp (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Updated <code>LoanService.record_repayment</code> to debit a single <code>-EMI</code> from the bank account (1:1 SMS/statement matching) while crediting only <code>principal_part</code> to the Loan account; added <code>is_prepayment</code> (100% principal with <code>is_emi=False</code> so amortization schedules don&#39;t falsely mark unpaid EMI months paid); and clamped <code>emi_date</code> days 29–31 in <code>_map_to_read_schema</code>.</li><li>Added <code>is_prepayment</code> toggle, decimal <code>step=&quot;any&quot;</code>, and live principal/interest split preview in Web <code>LoanRepaymentModal.vue</code> / <code>LoanDetails.vue</code> and Mobile <code>RecordRepaymentSheet</code>; fixed Mobile <code>LoanDetailModel.fromJson</code> preserving <code>lenderName</code> and <code>loanAccountNumber</code>.</li></ul></li><li><strong>FD Compounding, RD Multi-Installment Valuation &amp; PF Anchor Sync (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Fixed <code>timezone.timedelta</code> <code>AttributeError</code> in <code>fixed_deposit_service.py</code>, added shared <code>Decimal</code>-based <code>FixedDepositService.valuation()</code> for compound FD and multi-installment RD, and synced <code>last_synced_balance</code> + <code>BalanceSnapshot</code> on FD &amp; PF updates.</li><li>Exposed <code>compounding_frequency</code> &amp; <code>monthly_deposit</code> (RD) in Web <code>Deposits.vue</code> with aligned maturity compounding; updated Mobile <code>DepositModel</code> &amp; <code>DepositsScreen</code> to render actual compounding frequency and total RD invested principal.</li></ul></li><li><strong>Mutual Fund Pro-Rata LTCG Harvesting &amp; Per-Account SIP Liquidity (<code>Backend</code>)</strong>: <ul><li>Updated <code>MFTaxService</code> to pro-rate <code>suggested_units_to_sell</code> (4 decimal places) and expose <code>suggested_redemption_value</code> when lot gain exceeds remaining ₹1.25L headroom.</li><li>Updated <code>MFSipService</code> to scope bank liquidity by <code>user_id</code> and check each active SIP&#39;s <code>linked_account_id</code> bank balance individually against 7-day and 30-day commitments.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/finance/test_p1d_instruments_accuracy.py</code> (3 suites) and <code>Mobile-App/test/p1d_loans_and_deposits_test.dart</code> (2 tests).</li></ul></li></ul><h3 id="💳-credit-card-billing-math-mark-statement-as-paid-flow-p1-c-—-backend-web-app-mobile-app-test-suite-website" tabindex="-1">💳 Credit Card Billing Math &amp; &quot;Mark Statement as Paid&quot; Flow (<code>P1-C</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>, <code>Website</code>) <a class="header-anchor" href="#💳-credit-card-billing-math-mark-statement-as-paid-flow-p1-c-—-backend-web-app-mobile-app-test-suite-website" aria-label="Permalink to &quot;💳 Credit Card Billing Math &amp; &quot;Mark Statement as Paid&quot; Flow (`P1-C` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`, `Website`)&quot;">​</a></h3><ul><li><strong>IST Billing Cutoffs, Statement Balance &amp; Overdue Accuracy (<code>Backend</code>, <code>Web-App</code>)</strong>: <ul><li>Centralized <code>DEFAULT_BILLING_TZ = &quot;Asia/Kolkata&quot;</code> and UTC cutoff helpers (<code>billing_today</code>, <code>billing_day_start_utc</code>, <code>billing_day_end_utc</code>) in <code>Backend/app/core/timezone.py</code> and wired them into <code>CreditAnalytics</code> and <code>CreditCardService.get_cycle_transactions</code>.</li><li>Included bill payments regardless of <code>exclude_from_reports</code>, separated merchant refunds from bill payments (<code>net_unbilled = unbilled_debits - unbilled_refunds</code>; <code>statement_balance = max(0, balance - max(0, net_unbilled))</code>), and preserved overdue <code>due_date</code> when <code>statement_balance &gt; 0</code>.</li><li>Fixed <code>CreditWalletWidget.vue</code> (available limit/utilization from <code>card.balance</code>, overdue label, <code>/credit-cards/:id</code> routing), <code>CreditCards.vue</code> (<code>?? 999</code> due-today sort), and <code>WealthCompass.vue</code> (clamped over-limit utilization).</li></ul></li><li><strong>3-Mode &quot;Mark Statement as Paid&quot; (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added modular <code>CreditCardPaymentService</code> (<code>credit_card_payment_service.py</code>) supporting <code>NEW_TRANSFER</code>, <code>LINK_EXISTING</code> (via <code>GET /credit-cards/{id}/payment-candidates</code>), and <code>NO_SOURCE_ACCOUNT</code> (<code>MARK_PAID_PLACEHOLDER</code> with duplicate guard and automatic in-place claiming in <code>IngestionService</code> when the real issuer credit SMS arrives).</li><li>Exposed <code>/api/v1/finance/credit-cards/{id}/payment-candidates</code> &amp; <code>/mark-paid</code> (+ <code>/api/v1/mobile/*</code> mirrors), added reusable <code>MarkCardPaidModal.vue</code> wired into <code>AccountDetails.vue</code>, <code>CreditCards.vue</code>, and <code>CreditCardDetails.vue</code>, and upgraded Mobile <code>PayBillSheet</code> with all 3 payment modes.</li></ul></li><li><strong>Permanent Regression Tests &amp; How-To Guide (<code>Test-Suite</code>, <code>Mobile-App</code>, <code>Website</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/finance/test_p1c_credit_card_billing_and_mark_paid.py</code> (2 suites), <code>Mobile-App/test/p1c_credit_card_mark_paid_test.dart</code>, and <em>&quot;Paying &amp; Marking Credit Card Statements as Paid&quot;</em> in <code>Website/src/data/guideChaptersPart1.ts</code>.</li></ul></li></ul><h3 id="📥-ingestion-pipeline-parser-accuracy-mobile-sms-sync-hardening-p1-b-—-parser-backend-mobile-app-test-suite" tabindex="-1">📥 Ingestion Pipeline, Parser Accuracy &amp; Mobile SMS Sync Hardening (<code>P1-B</code> — <code>Parser</code>, <code>Backend</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#📥-ingestion-pipeline-parser-accuracy-mobile-sms-sync-hardening-p1-b-—-parser-backend-mobile-app-test-suite" aria-label="Permalink to &quot;📥 Ingestion Pipeline, Parser Accuracy &amp; Mobile SMS Sync Hardening (`P1-B` — `Parser`, `Backend`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Parser Date/Timezone Normalization &amp; Batch Pipeline Parity (<code>Parser</code>)</strong>: <ul><li>Added shared <code>Parser/core/date_utils.py</code> (<code>coerce_date_hint</code>, <code>ist_to_utc</code>, <code>combine_date_with_hint</code>) and wired it into <code>BaseParser._parse_date</code>, <code>GenericEmailParser</code>, <code>SbiSmsParser</code>, and <code>SliceSmsParser</code> so naive IST bank timestamps convert cleanly to aware UTC (eliminating <code>+5h30m</code> shifts) and string <code>date_hint</code>s never raise <code>AttributeError</code>.</li><li>Updated <code>IngestionPipeline.run</code> to forward <code>sender=sender</code> to email parsers&#39; <code>can_handle(...)</code>, updated <code>BatchIngestionPipeline.run_batch</code> to preserve <code>ref_id</code>, <code>balance</code>, <code>credit_limit</code>, <code>category</code> and run <code>MerchantNormalizer</code>/<code>TransactionValidator.enrich_time</code>/<code>CategoryGuesser</code>, and fixed <code>icici_savings.py</code> column classification with right-anchored amount lookup.</li></ul></li><li><strong>Credit Card Available-Limit Guard (<code>Parser</code>, <code>Backend</code>)</strong>: <ul><li>Removed <code>&quot;balance&quot;</code> captures from Credit Card <code>Avail. Limit</code> / <code>Available Limit</code> patterns in <code>onecard.py</code>, <code>hsbc.py</code>, and <code>scb.py</code>; excluded <code>Avl/Avbl/Avail/Available</code> prefixes from <code>hdfc.py</code> <code>LIMIT_PATTERN</code>; and blocked <code>IngestionService</code> and <code>import_csv</code> from overwriting <code>CREDIT_CARD</code> balances from <code>parsed.balance</code> (syncing <code>credit_limit</code> only).</li></ul></li><li><strong>Backend Ingestion Deduplication, Account Matching &amp; Statement Sign Guards (<code>Backend</code>)</strong>: <ul><li>Updated <code>import_csv</code> to normalize <code>txn_date</code> to UTC and run <code>TransactionDeduplicator.check_raw_duplicate</code> <em>before</em> mutating <code>last_synced_balance</code>/<code>BalanceSnapshot</code>.</li><li>Scoped <code>TransactionDeduplicator</code> <code>external_id</code>/<code>ref_id</code> lookups by <code>account_id</code> so cross-account same-UTR transfer legs are preserved; filtered <code>Account.is_deleted == False</code> and rejected <code>&lt; 2</code>-digit masks (e.g., <code>&quot;XX&quot;</code>) in <code>IngestionService.match_account</code>; enforced <code>abs()</code> sign guards in <code>statements.py</code> and <code>statement_processor.py</code>.</li></ul></li><li><strong>Mobile Android SMS Sync Hardening (<code>Mobile-App</code>)</strong>: <ul><li>Added modular <code>SmsSyncUtils</code> (<code>sms_sync_utils.dart</code>) with UTC hour-precision <code>computeHash</code>, atomic <code>.json</code> → <code>.processing</code> relay file claiming/release (paired with atomic <code>.tmp</code> → <code>.json</code> writes in <code>SmsReceiver.kt</code>), and background <code>401</code> token refresh (<code>/api/v1/auth/refresh</code>); wired <code>401</code> recovery into <code>SyncTaskHandler</code> and <code>SmsService</code> and awaited <code>_performCatchUpScan()</code> before draining relay files.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/ingestion/test_p1b_ingestion_and_parser_hardening.py</code> (6 tests) and <code>Mobile-App/test/p1b_sms_sync_hardening_test.dart</code> (3 tests).</li></ul></li></ul><h3 id="⚖️-core-ledger-smart-balance-engine-transfer-integrity-p1-a-—-backend-web-app-mobile-app-test-suite" tabindex="-1">⚖️ Core Ledger, Smart Balance Engine &amp; Transfer Integrity (<code>P1-A</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#⚖️-core-ledger-smart-balance-engine-transfer-integrity-p1-a-—-backend-web-app-mobile-app-test-suite" aria-label="Permalink to &quot;⚖️ Core Ledger, Smart Balance Engine &amp; Transfer Integrity (`P1-A` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Smart Balance Mode (<code>CALCULATED</code> vs <code>DERIVED</code>) &amp; Anchor Boundary Fix (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>opening_balance</code>, <code>balance_mode</code> (<code>CALCULATED</code> | <code>DERIVED</code>), and <code>balance_source</code> (<code>CALCULATED</code> | <code>STATEMENT</code> | <code>SMS</code> | <code>EMAIL</code> | <code>MANUAL_OVERRIDE</code>) on <code>Account</code> via idempotent Alembic migration <code>n5i6j7k8l9m0</code> (with smart backfill for existing Bank/CC/Wallet accounts).</li><li>Centralized <code>AccountService.balance_delta()</code>, <code>counts_toward_balance()</code> (strict <code>&gt;</code> for <code>DERIVED</code>, all active txns for <code>CALCULATED</code>), <code>compute_expected_balance()</code>, and <code>recalculate_balance()</code>; wired <code>override_balance()</code> to replay post-anchor transactions and <code>BackupService</code> to preserve new columns and recalculate ledger balances after <code>.wfam</code> restore.</li><li>Added optional <code>as_of</code> date (rejecting future dates) to <code>AccountCreate</code> and <code>CreditCardCreate</code> (switching accounts with explicit <code>as_of</code> to <code>DERIVED</code>), fixed <code>AccountEditModal.vue</code> CC creation field mapping (<code>initial_balance</code>/<code>card_last_4</code>), fixed Mobile <code>add_edit_account_sheet.dart</code> credit-limit-only anchor stamping and <code>accounts_repository.dart</code> type-switch 404, and added Asset ↔ Liability type-switch recalculation in <code>AccountService.update_account</code>.</li></ul></li><li><strong><code>Transaction.type</code> Sign Invariant (<code>Backend</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added SQLAlchemy <code>before_insert</code>/<code>before_update</code> listeners on <code>Transaction</code> enforcing <code>amount &lt; 0 → DEBIT</code>, <code>amount &gt;= 0 → CREDIT</code> (plus pre-flush derivation in <code>create_transaction</code>, migration <code>n5i6j7k8l9m0</code> backfill, and <code>BackupService</code> merge-dedupe <code>t_sig</code> alignment), and simplified Mobile <code>TransactionModel.isExpense</code>/<code>isIncome</code> to check <code>amount</code> sign cleanly.</li></ul></li><li><strong>Bulk Delete, Transfer Sign &amp; Orphan Integrity (<code>Backend</code>, <code>Web-App</code>)</strong>: <ul><li>Filtered <code>is_deleted == False</code> in <code>bulk_delete_transactions</code>, normalized <code>TransferService.create_transfer</code> with <code>abs(Decimal)</code> + inflow direction handling in <code>approve_transfer</code>, wired <code>batch_update_category_and_create_rule</code> to <code>TransferDetectionService.create_counterpart_leg(..., commit=False)</code>, cleared <code>db_txn.linked_transaction_id = None</code> on unlink and synced mirrored amount/date edits onto transfer counterparts.</li><li>Hardened <code>AccountService.delete_account</code> (unlinking transfer counterparts, soft-deleting 1:1 instrument details, nulling dangling FKs), <code>RuleExecutor</code> (unlinking both transfer legs), <code>TransferDetectionService</code> (excluding soft-deleted accounts), and <code>Transfers.vue</code> (<code>suggested_destination?.id</code> null guard).</li></ul></li><li><strong>Midnight Balance-Drift Audit, Attention Hub &amp; 1-Click Reconcile (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>balance_drift_amount</code> &amp; <code>balance_drift_checked_at</code> on <code>Account</code> (Alembic migration <code>o6j7k8l9m0n1</code>), daily midnight IST scheduler job (<code>daily_balance_drift_audit_job</code> at <code>18:30 UTC</code>), <code>ACCOUNT_BALANCE_DRIFT</code> alerts in <code>AttentionService</code> (shielded from <code>CHILD</code>), <code>GET /api/v1/finance/accounts/audit/balance-drift</code> + <code>POST /api/v1/finance/accounts/audit/reconcile</code>, and 1-click <strong>Reconcile</strong> banners in Web <code>AccountDetails.vue</code> and Mobile <code>AccountDetailScreen</code> (auto-clearing drift on reconcile).</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/finance/test_p1a_ledger_and_balance_engine.py</code> (7 tests) and <code>Mobile-App/test/p1a_models_test.dart</code> (3 tests).</li></ul></li></ul><h3 id="🚑-runtime-crash-fixes-vault-detach-safety-mobile-403-handling-p0-b-—-backend-web-app-mobile-app-test-suite" tabindex="-1">🚑 Runtime Crash Fixes, Vault Detach Safety &amp; Mobile 403 Handling (<code>P0-B</code> — <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#🚑-runtime-crash-fixes-vault-detach-safety-mobile-403-handling-p0-b-—-backend-web-app-mobile-app-test-suite" aria-label="Permalink to &quot;🚑 Runtime Crash Fixes, Vault Detach Safety &amp; Mobile 403 Handling (`P0-B` — `Backend`, `Web-App`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Backend <code>NameError</code> Fixes (<code>Backend</code>)</strong>: <ul><li>Added missing <code>from backend.app.core import timezone</code> imports in <code>InvestmentGoalService</code> (<code>investment_goal_service.py</code>) and <code>ExpenseGroupService</code> (<code>expense_group_service.py</code>), and defined module-level <code>logger = logging.getLogger(__name__)</code> in <code>EmailSyncService</code> (<code>email_sync.py</code>).</li></ul></li><li><strong>Safe Document Detach (<code>Web-App</code>)</strong>: <ul><li>Updated <code>detachDoc</code> in <code>Web-App/src/views/transactions/TransactionModal.vue</code> to call <code>financeApi.linkDocToTransaction(docId, null)</code> instead of <code>financeApi.deleteDocument(docId)</code> (preventing permanent Vault file deletion) and replaced the <code>&lt;Trash2&gt;</code> icon with <code>&lt;Unlink&gt;</code>.</li></ul></li><li><strong>Mobile 403 Permission Handling &amp; Family Account/Vault Access (<code>Mobile-App</code>, <code>Backend</code>)</strong>: <ul><li>Updated <code>NetworkResilience.callWithResilience</code> and <code>callWithResilienceBytes</code> (<code>network_resilience.dart</code>) so <code>HTTP 403</code> returns <code>SecurityFailure</code> with the backend error detail instead of invoking <code>onUnauthorized()</code> / logging out.</li><li>Updated <code>POST /api/v1/mobile/transactions</code> (<code>mobile/api/router.py</code>) to allow <code>OWNER</code>/<code>ADULT</code> users to post to any family account in the tenant while restricting <code>CHILD</code> users to their own/shared non-investment, non-credit accounts, and updated <code>DELETE /api/v1/mobile/vault/{document_id}</code> to reuse <code>CoreVaultService.can_modify_document</code>.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/finance/test_p0b_crashes_and_rbac.py</code> (5 tests) and <code>Mobile-App/test/p0b_network_403_test.dart</code> (3 tests).</li></ul></li></ul><h3 id="🛡️-multi-tenancy-rbac-crypto-isolation-mobile-privacy-hotfixes-p0-a-—-backend-mobile-app-test-suite" tabindex="-1">🛡️ Multi-Tenancy, RBAC, Crypto Isolation &amp; Mobile Privacy Hotfixes (<code>P0-A</code> — <code>Backend</code>, <code>Mobile-App</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#🛡️-multi-tenancy-rbac-crypto-isolation-mobile-privacy-hotfixes-p0-a-—-backend-mobile-app-test-suite" aria-label="Permalink to &quot;🛡️ Multi-Tenancy, RBAC, Crypto Isolation &amp; Mobile Privacy Hotfixes (`P0-A` — `Backend`, `Mobile-App`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Cross-Tenant Account &amp; Goal Isolation (<code>Backend</code>)</strong>: <ul><li>Hardened <code>TransactionService</code> (<code>create_transaction</code>, <code>update_transaction</code>, <code>bulk_delete_transactions</code>, <code>approve_pending_transaction</code>, <code>batch_update_category_and_create_rule</code>) to validate <code>account_id</code> and <code>to_account_id</code> against <code>(tenant_id, is_deleted=False)</code> upfront regardless of <code>update_balance</code>, and scoped every <code>Account</code> query/update by <code>tenant_id</code>.</li><li>Hoisted <code>InvestmentGoal.tenant_id == tenant_id</code> ownership validation above the aggregate <code>group_&lt;scheme_code&gt;</code> branch in <code>InvestmentGoalService.link_holding_to_goal</code> while preserving <code>goal_id=None</code> unlinking.</li></ul></li><li><strong>Scheduler &amp; Email Sync Crypto Context Isolation + Rollback Hardening (<code>Backend</code>)</strong>: <ul><li>Added <code>crypto_tenant_context(tenant_id)</code> context manager in <code>Backend/app/core/crypto/types.py</code> (restoring the <code>ContextVar</code> token in <code>finally</code>).</li><li>Updated all multi-tenant background jobs in <code>Backend/app/core/scheduler.py</code> (<code>daily_recurrence_check</code>, <code>auto_sync_job</code>, <code>mutual_fund_sync_job</code>, <code>pulse_check_job</code>, <code>daily_summary_job</code>) to use <code>crypto_tenant_context</code>, per-tenant <code>SessionLocal()</code> with explicit <code>db.rollback()</code>, and graceful <code>TenantSealedException</code> skipping.</li><li>Wrapped <code>EmailSyncService.sync_emails</code> in <code>crypto_tenant_context</code> and propagated <code>contextvars.copy_context()</code> into <code>ThreadPoolExecutor</code> statement worker threads in <code>Backend/app/modules/ingestion/email_sync.py</code>.</li></ul></li><li><strong>Mobile Device Management RBAC &amp; Tenant Validation (<code>Backend</code>)</strong>: <ul><li>Enforced adult-only RBAC (<code>_require_adult_for_device_mgmt</code>, blocking <code>CHILD</code> with <code>403</code>) across all 6 device endpoints in <code>Backend/app/modules/mobile/api/router.py</code> (<code>approve_device</code>, <code>delete_device</code>, <code>update_device</code>, <code>toggle_device_enabled</code>, <code>toggle_device_ignored</code>, <code>assign_device_user</code>) and validated <code>user_id</code> belongs to the caller&#39;s tenant (<code>_validate_tenant_device_user</code>).</li></ul></li><li><strong>Mobile Logout Foreground Service Cleanup &amp; Catch-Up SMS Privacy Filter (<code>Mobile-App</code>)</strong>: <ul><li>Updated <code>AuthService</code> (<code>auth_service.dart</code>) to stop <code>ForegroundServiceWrapper</code>, wipe <code>FlutterForegroundTask</code> persisted keys (<code>access_token</code>, <code>backend_url</code>, <code>device_id</code>, <code>notif_masking_factor</code>), and clear <code>sms_offline_queue</code> on logout and local session wipe.</li><li>Added <code>SyncTaskHandler.shouldIngestSms()</code> in <code>foreground_task_handler.dart</code> requiring <code>_transactionPattern</code> match during <code>_performCatchUpScan()</code> for exact privacy parity with <code>SmsReceiver.kt</code>.</li></ul></li><li><strong>Permanent Regression Tests (<code>Test-Suite</code>, <code>Mobile-App</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/auth/test_p0a_security_isolation.py</code> (8 tests) and <code>Mobile-App/test/p0a_sms_privacy_test.dart</code> (4 tests); verified full <code>Test-Suite</code> (<code>329 passed, 1 xpassed, 0 failed</code>).</li></ul></li></ul><hr><h2 id="_3-0-36-—-2026-11-25-archived-completed-backlog" tabindex="-1">[3.0.36] — 2026-11-25 (Archived Completed Backlog) <a class="header-anchor" href="#_3-0-36-—-2026-11-25-archived-completed-backlog" aria-label="Permalink to &quot;[3.0.36] — 2026-11-25 (Archived Completed Backlog)&quot;">​</a></h2><h3 id="🛡️-error-analytics-vault-seal-guard-frontend-test-coverage-admin-web-admin-backend-backend-test-suite" tabindex="-1">🛡️ Error Analytics, Vault Seal Guard &amp; Frontend Test Coverage (<code>Admin-Web</code>, <code>Admin-Backend</code>, <code>Backend</code>, <code>Test-Suite</code>) <a class="header-anchor" href="#🛡️-error-analytics-vault-seal-guard-frontend-test-coverage-admin-web-admin-backend-backend-test-suite" aria-label="Permalink to &quot;🛡️ Error Analytics, Vault Seal Guard &amp; Frontend Test Coverage (`Admin-Web`, `Admin-Backend`, `Backend`, `Test-Suite`)&quot;">​</a></h3><ul><li><strong>Dedicated Error Analytics Page (<code>Admin-Web</code>, <code>Admin-Backend</code>)</strong>: <ul><li>Added <code>GET /v1/telemetry/errors/analytics</code> in <code>Admin-Backend/app/api/telemetry.py</code> aggregating DuckDB <code>telemetry_system_logs</code> and <code>telemetry_api_metrics</code> with cross-filtering (<code>window_hours</code>, <code>service</code>, <code>level</code>, <code>exception_type</code>, <code>route</code>, <code>status_code</code>, <code>bucket</code>, <code>search</code>).</li><li>Built <code>Admin-Web/src/views/ErrorAnalyticsView.vue</code> (<code>/errors</code>) with 4 clickable cross-filtering Chart.js visualizations (hourly error volume, service breakdown, top exception types, top failing API routes), grouped error signatures, expandable stack traces, and 1-click copy buttons for messages and full tracebacks.</li></ul></li><li><strong>Sealed Tenant Session Handling &amp; Mobile Alerts Fix (<code>Backend</code>)</strong>: <ul><li>Enforced <code>KeyRingService.is_unsealed(tenant_id)</code> in <code>get_current_user</code> (<code>Backend/app/modules/auth/dependencies.py</code>) and added <code>TenantSealedException</code> unwrapping in <code>generic_exception_handler</code> (<code>Backend/app/core/exceptions.py</code>), returning <code>HTTP 401</code> (<code>code: &quot;TENANT_SEALED&quot;</code>) so clients cleanly prompt re-login after server restarts instead of failing with 500 on encrypted column writes (such as transfer pairing location inheritance).</li><li>Fixed <code>AttributeError</code> in <code>GET /api/v1/mobile/alerts/history</code> (<code>Backend/app/modules/mobile/api/router.py</code>) by removing non-existent <code>Alert.severity</code> and <code>Alert.payload</code> accesses and returning <code>Alert.icon</code>.</li></ul></li><li><strong>Web-App &amp; Admin-Web Test Module (<code>Test-Suite</code>)</strong>: <ul><li>Added <code>Test-Suite/modules/web_app/test_web_app.py</code> running <code>Web-App</code> Vitest unit specs, <code>Web-App</code> and <code>Admin-Web</code> <code>vue-tsc &amp;&amp; vite build</code> checks, router view existence checks, and live SPA smoke tests.</li></ul></li></ul><h3 id="🗺️-visuals-geo-intelligence" tabindex="-1">🗺️ Visuals &amp; Geo-Intelligence <a class="header-anchor" href="#🗺️-visuals-geo-intelligence" aria-label="Permalink to &quot;🗺️ Visuals &amp; Geo-Intelligence&quot;">​</a></h3><ul><li><strong>Full-Screen Interactive Spending Map (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Enriched <code>GET /api/v1/finance/analytics/heatmap</code> and <code>GET /api/v1/mobile/heatmap</code> with transaction metadata (<code>id</code>, <code>date</code>, <code>recipient</code>, <code>category_id</code>, <code>category_color</code>, <code>category_icon</code>, <code>account_id</code>, <code>account_name</code>, <code>expense_group_id</code>) and SQL filter support (<code>period=&quot;all&quot;</code>, <code>category_ids</code>, <code>account_id</code>, <code>expense_group_id</code>, <code>min_amount</code>, <code>max_amount</code>, <code>search</code>) while preserving RFC 0001 encrypted coordinate storage.</li><li>Built dedicated full-screen Web-App view (<code>/spending-map</code> in <code>SpendingMap.vue</code>) with <code>leaflet.markercluster</code> cluster-zoom (count + total spend pills), Hybrid/Pins/Heat layer switcher, theme-aware Carto basemaps, privacy-first location &amp; merchant search (<code>useLocationSearch.ts</code> with OpenStreetMap Nominatim + local matches), pin filters, and live viewport summary inspector.</li><li>Built dedicated full-screen Mobile-App screen (<code>SpendingMapScreen</code>) with zero-dependency zoom-aware spatial grid clustering, Hybrid/Pins/Heat modes, floating location &amp; merchant search, category/period filters, and a draggable viewport transaction sheet, launched via a &quot;Full Map&quot; button on <code>SpendingHeatmapWidget</code>.</li></ul></li></ul><h3 id="🔐-enterprise-pii-encryption-vault-at-rest-zero-retention-ingestion-rfc-0001-backend-parser-test-suite-docs" tabindex="-1">🔐 Enterprise PII Encryption, Vault at Rest &amp; Zero-Retention Ingestion (<a href="./RFCs/0001-modular-pii-vault-encryption.html">RFC 0001</a>, <code>Backend</code>, <code>Parser</code>, <code>Test-Suite</code>, <code>Docs</code>) <a class="header-anchor" href="#🔐-enterprise-pii-encryption-vault-at-rest-zero-retention-ingestion-rfc-0001-backend-parser-test-suite-docs" aria-label="Permalink to &quot;🔐 Enterprise PII Encryption, Vault at Rest &amp; Zero-Retention Ingestion ([RFC 0001](./RFCs/0001-modular-pii-vault-encryption.md), `Backend`, `Parser`, `Test-Suite`, `Docs`)&quot;">​</a></h3><ul><li><strong>Modular Cryptography Engine (<code>Backend/app/core/crypto/</code>)</strong>: <ul><li><strong>AES-256-GCM AEAD Envelope Cipher (<code>ciphers.py</code>)</strong>: Implemented high-speed authenticated encryption with versioned envelopes (<code>enc:v1:&lt;iv_hex&gt;:&lt;ciphertext_hex&gt;</code>) protecting data against tampering and bit-flipping attacks.</li><li><strong>Thread-Safe In-Memory KeyRing (<code>keyring.py</code>)</strong>: Implemented volatile in-memory DEK manager with deterministic PBKDF2-HMAC fallback derivation, enabling 24/7 background automations (such as email ingestion and statement parsing) without user interaction while keeping tenant keys out of persistent disks.</li><li><strong>Blind Index Service (<code>blind_index.py</code>)</strong>: Implemented deterministic HMAC-SHA256 blind indexing with dedicated salt isolation for exact-match database queries without plaintext leakage.</li><li><strong>Transparent SQLAlchemy Custom Types (<code>types.py</code>)</strong>: Created <code>EncryptedString</code>, <code>EncryptedText</code>, <code>EncryptedNumeric</code>, and <code>EncryptedJSON</code> with thread-safe <code>contextvars</code> tenant key propagation (<code>set_crypto_tenant</code>), ensuring ledger math (<code>amount</code>, <code>date</code>, <code>category_id</code>, <code>balance</code>) remains standard SQL types for sub-5ms aggregations.</li><li><strong>Streaming 64KB Chunked Vault Cipher (<code>vault_cipher.py</code>)</strong>: Created memory-bounded AES-GCM streaming encryption with magic header (<code>b&quot;WFENC\\x01&quot;</code>), guaranteeing zero plaintext storage on disk for physical documents, statement PDFs, and thumbnails while preserving existing folder hierarchies and file paths.</li></ul></li><li><strong>Data Models, Hybrid Properties &amp; Zero-Downtime Migrations (<code>Backend</code>)</strong>: <ul><li><strong>Hybrid Property Comparators</strong>: Re-engineered <code>User.email</code>, <code>phone_number</code>, <code>pan_number</code> and <code>Account.account_number</code> as SQLAlchemy hybrid properties with custom <code>Comparator</code> classes routing equality checks to blind indexes (<code>email_bindex</code>, <code>phone_bindex</code>, <code>pan_bindex</code>, <code>account_bindex</code>).</li><li><strong>Encrypted PII Columns</strong>: Encrypted <code>User.full_name</code>, <code>EmailConfiguration.password</code>, <code>Transaction.latitude</code>/<code>longitude</code>, and <code>Statement.email_body</code>.</li><li><strong>Database Migration <code>i0d1e2f3g4h5</code></strong>: Added blind index columns, widened <code>latitude</code>/<code>longitude</code> to <code>VARCHAR</code>, and backfilled user blind indices.</li><li><strong>Database Migration <code>j1e2f3g4h5i6</code></strong>: Truncated <code>unparsed_messages</code>, purged legacy raw email bodies (<code>raw_content = NULL</code>), widened <code>statements.email_body</code> to <code>TEXT</code>, and migrated existing plaintext email password hints to AES-256-GCM ciphertexts.</li></ul></li><li><strong>Zero-Retention Ingestion &amp; Ephemeral Vault Processing (<code>Backend</code>, <code>Parser</code>)</strong>: <ul><li>Removed raw message body retention from <code>ParsedTransaction</code> (<code>raw_message: Optional[str] = None</code>), event logs, and email sync logs while preserving temporary triage search capabilities.</li><li>Implemented ephemeral decrypted file preparation in <code>VaultService.prepare_readable_file_path()</code> with background task file cleanup for PyMuPDF statement parsing.</li></ul></li><li><strong>PII &amp; Ciphertext Telemetry Redaction (<code>Backend</code>, <code>Parser</code>)</strong>: <ul><li>Upgraded <code>AsyncHttpLogHandler</code> and <code>scrub_text()</code> to redact emails, phone numbers, PANs, JWTs, and versioned ciphertexts (<code>[REDACTED_CIPHERTEXT]</code>) before logging or transmission to Admin platforms.</li></ul></li><li><strong>Hermetic Verification &amp; Test Suite (<code>Test-Suite</code>)</strong>: <ul><li>Authored unit and ORM tests (<code>test_core_crypto.py</code> and <code>test_encrypted_orm_and_zero_retention.py</code>).</li><li>Verified 100% clean test execution: <strong>290 / 290 PASSED</strong>, 0 errors, 0 warnings across backend, parser, and admin apps.</li></ul></li></ul><h3 id="📱-mobile-ux-dashboard-alignment-document-scanner" tabindex="-1">📱 Mobile UX, Dashboard Alignment &amp; Document Scanner <a class="header-anchor" href="#📱-mobile-ux-dashboard-alignment-document-scanner" aria-label="Permalink to &quot;📱 Mobile UX, Dashboard Alignment &amp; Document Scanner&quot;">​</a></h3><ul><li><strong>Mobile Dashboard Alignment (<code>Mobile-App</code>)</strong>: <ul><li><strong>Investment Classification</strong>: Updated mobile transaction entry (<code>add_transaction_screen.dart</code>), triage sheet, and edit sheets to support the <code>investment</code> category type with 3-tab segmented control and category scoping.</li><li><strong>Unified Savings Rate</strong>: Synced mobile &quot;Wealth Compass&quot; to use updated logic: <code>Savings = Income - Operational Expenses</code> (excluding <code>investment</code> transactions).</li><li><strong>Trend Sparklines</strong>: Rendered 6-month investment and spending mini-sparklines on mobile using <code>/analytics/history</code> and smooth Bézier curve <code>SparklineWidget</code>.</li></ul></li><li><strong>Mobile UX &amp; Accessibility Polish (<code>Mobile-App</code>)</strong>: <ul><li>Completed comprehensive mobile touch target polish and accessibility audit (enforced $\\ge 48\\times 48\\text{ dp}$ primary targets, $36\\times 36\\text{ dp}$ secondary targets, and accessible Sheet close buttons).</li><li><strong>Activity Hub &amp; Notification Streamlining</strong>: Wired persistent database alert stream (<code>GET /api/v1/mobile/alerts/history</code>) to eliminate empty Activity tab, removed redundant background HTTP polling loop to deduplicate push alerts.</li></ul></li><li><strong>Native Receipt &amp; Document Scanner with Straightening (<code>Mobile-App</code>, <code>Vault</code>)</strong>: <ul><li>Native document scanner integration (<code>DocumentScannerService</code> wrapping Google ML Kit with auto-edge detection, perspective straightening, shadow cleaning, and corner adjustment, plus <code>DocumentCaptureSheet</code> in transaction details and Vault).</li></ul></li></ul><h3 id="🟡-architecture-tech-debt-quality-hardening" tabindex="-1">🟡 Architecture, Tech Debt &amp; Quality Hardening <a class="header-anchor" href="#🟡-architecture-tech-debt-quality-hardening" aria-label="Permalink to &quot;🟡 Architecture, Tech Debt &amp; Quality Hardening&quot;">​</a></h3><ul><li><strong>Unified Income, Expense &amp; Investment Calculation Alignment &amp; Relational <code>category_id</code> Foreign Keys (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Docs</code>)</strong>: <ul><li><strong>Relational <code>category_id</code> Foreign Keys &amp; Migrations (<code>g8b9c0d1e2f3</code>, <code>h9c0d1e2f3g4</code>)</strong>: Added <code>transactions.category_id</code> and <code>budgets.category_id</code> foreign keys (<code>ON DELETE SET NULL</code>) referencing <code>categories.id</code>, normalized <code>Category.type</code> (<code>&#39;income&#39;</code>, <code>&#39;expense&#39;</code>, <code>&#39;investment&#39;</code>, <code>&#39;transfer&#39;</code>), seeded default <code>&#39;Other&#39;</code> (<code>expense</code>) and <code>&#39;Transfer&#39;</code> (<code>transfer</code>) categories per tenant, split ambiguous <code>Gift</code> categories (<code>Gift Received</code> as <code>&#39;income&#39;</code> vs <code>Gifts &amp; Donations</code> as <code>&#39;expense&#39;</code>), enforced Zero-Uncategorized policy (<code>category_id IS NOT NULL</code>), and backfilled all transactions and budgets.</li><li><strong>Category-Aware Income, Expense Refund Netting &amp; Investment Liquidation Separation (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: Unified all analytics and ledger views (<code>core.py</code>, <code>spending.py</code>, <code>history.py</code>, <code>investments.py</code>, <code>budget_service.py</code>, <code>expense_group_service.py</code>, <code>search.py</code>, <code>mobile/api/router.py</code>, Web <code>Transactions</code>, <code>MerchantDetails</code>, <code>CategoryDetailsModal</code>, <code>ExpenseGroupModal</code>, and Mobile <code>TransactionsScreen</code>, <code>MerchantDetailScreen</code>, <code>AnalyticsMerchantsTab</code>, <code>ExpenseGroupDetailsScreen</code>) to join on <code>Transaction.category_id == Category.id</code>, strictly classify Operating Income (<code>Category.type == &#39;income&#39;</code>), net positive expense refunds against gross debits (<code>max(0, debits - refunds)</code>), isolate investment redemptions (<code>Category.type == &#39;investment&#39;</code>), and universally exclude transfers and hidden items (<code>exclude_from_reports == False &amp;&amp; is_transfer == False</code>).</li><li><strong>Date Range Scope Alignment &amp; Default Current Month (<code>Web-App</code> &amp; <code>Backend</code>)</strong>: Defaulted <code>/transactions</code> filter (<code>useTransactionState.ts</code>) to <code>&#39;this-month&#39;</code> and added <code>period=&#39;all&#39;</code> support across <code>getMetrics</code> and <code>getDetailedAnalytics</code> (<code>/analytics/detailed</code> &amp; <code>/analytics/spending/detailed</code>) so &quot;All Time&quot; KPI strip metrics match the unfiltered ledger table instead of silently falling back to <code>today.month</code>.</li><li><strong>Bilateral Transfer Symmetry, Credit Card Bill Payment Pairing &amp; FK Sanitization (<code>Backend</code> &amp; <code>Web-App</code>)</strong>: Fixed <code>CreditCardDetails.statement_balance</code> adjustment on transfer pairing/unpairing (<code>credit_card_service.py</code> &amp; <code>transfer_detection_service.py</code>), enforced bilateral <code>(is_transfer, exclude_from_reports, linked_transaction_id, Transfer category)</code> symmetry across both legs on create/update/pair/unpair/delete, and added <code>OptionalFK</code> / <code>OptionalUUIDFK</code> (<code>BeforeValidator</code>) across all Pydantic schemas so empty strings (<code>&quot;&quot;</code>) from UI forms are normalized to <code>None</code>.</li><li><strong>Mobile WebSocket RFC Handshake &amp; Web UI Polish (<code>Mobile-App</code> &amp; <code>Web-App</code>)</strong>: Updated <code>socket_service.dart</code> to authenticate via <code>Sec-WebSocket-Protocol: [&#39;wealthfam-auth&#39;, token]</code>; resolved <code>MainLayout.vue</code> store initialization order, guarded empty <code>/merchants/</code> links, added <code>size</code> prop &amp; <code>inheritAttrs: false</code> on <code>WfModal.vue</code>, and fixed immediate PDF Blob preview rendering in <code>FilePreviewModal.vue</code>.</li></ul></li><li><strong>PyMuPDF Modernization (<code>Backend</code>, <code>Parser</code>, <code>Test-Suite</code>)</strong>: <ul><li>Migrated legacy <code>import fitz</code> statements across <code>Backend</code> (<code>password_service.py</code>, <code>cas_handler.py</code>, <code>vault/service.py</code>, <code>statement_processor.py</code>), <code>Parser</code> (<code>amc_soa.py</code>), and <code>Test-Suite</code> (<code>test_amc_soa_parser.py</code>, <code>test_statement_crud_and_ignore.py</code>, <code>test_storage_vault_hardening.py</code>) to canonical <code>import pymupdf as fitz</code>, completely silencing PyMuPDF deprecation warnings ahead of PyMuPDF 2.0.</li></ul></li><li><strong>Python 3.14 PEP 706 Tarfile Extraction Filter Compliance (<code>Infra</code>, <code>Test-Suite</code>)</strong>: <ul><li>Implemented safe extraction helper <code>safe_extractall</code> passing <code>filter=&quot;data&quot;</code> (with backwards-compatible <code>hasattr(tarfile, &quot;data_filter&quot;)</code> fallback) to <code>tarfile.extractall()</code> in <code>Infra/scripts/maintenance/restore.py</code> and <code>Test-Suite/modules/infra/test_backup_restore.py</code>, silencing Python 3.12+ <code>DeprecationWarning</code> and hardening against path traversal attacks ahead of Python 3.14. Added automated directory traversal security verification test.</li></ul></li><li><strong>Web-App Bundle Chunk Code-Splitting (<code>Web-App</code>)</strong>: <ul><li>Configured Rollup <code>output.manualChunks</code> in <code>Web-App/vite.config.ts</code> to split vendor libraries (<code>vendor-vue</code>, <code>vendor-charts</code>, <code>vendor-maps</code>, <code>vendor-ui</code>, <code>vendor-utils</code>, <code>vendor-core</code>) and dynamic route lazy-loading (<code>Dashboard</code>, <code>Login</code>, <code>Register</code>) in <code>router/index.ts</code>. Reduced monolithic <code>dist/assets/index-*.js</code> bundle from 560 kB down to 40.6 kB, with zero chunks exceeding Vite&#39;s 500 kB warning threshold.</li></ul></li><li><strong>Soft-Delete Governance (<code>Backend</code>)</strong>: <ul><li>Implemented dedicated <code>governance</code> module (<code>Backend/app/modules/governance/</code>) with topological cascading hard-purges, <code>RetentionPurgeLog</code> audit history, admin API router (<code>/api/v1/governance/purge</code>), and CLI maintenance script (<code>Infra/scripts/maintenance/purge_soft_deleted.py</code>). Configurable retention window (default 7 years / 2555 days) and multi-tenant isolation.</li></ul></li><li><strong>Automatic Session Timeout (<code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: <ul><li>Implemented 15-minute inactivity timeout with interactive 60-second visual countdown modal (<code>TimeoutWarningModal.vue</code>), multi-tab synchronization (<code>useIdleTimeout.ts</code>), and backend token extension (<code>POST /api/v1/auth/refresh</code>). Added in-foreground pointer touch inactivity monitoring in <code>Mobile-App</code> (<code>BiometricGate</code>).</li></ul></li><li><strong>Testing Infrastructure (<code>Web-App</code> &amp; <code>Test-Suite</code>)</strong>: <ul><li>Configured <code>vitest</code> with JSDOM and <code>@vue/test-utils</code> for <code>Web-App</code> (<code>npm run test</code>), providing unit testing and regression guards for Pinia stores and composables (<code>auth.spec.ts</code>, <code>useIdleTimeout.spec.ts</code>).</li><li>Created hermetic end-to-end integration test runner in <code>Test-Suite/modules/e2e/test_full_pipeline_flow.py</code> validating the entire lifecycle: <code>Parser -&gt; Backend Persistence &amp; Delta -&gt; Frontend Data Schema Contract</code>.</li></ul></li><li><strong>New SMS Formats (<code>Parser</code>)</strong>: <ul><li>Expanded parser coverage for modern Indian bank and fintech SMS/Email formats across 10 institutions: Standard Chartered (<code>scb.py</code>), HSBC (<code>hsbc.py</code>), DBS / digibank (<code>dbs.py</code>), OneCard (<code>onecard.py</code>), Airtel Payments Bank (<code>airtel.py</code>), Equitas SFB (<code>equitas.py</code>), CRED (<code>cred.py</code>), Bank of Maharashtra (<code>bom.py</code>), Indian Overseas Bank (<code>iob.py</code>), and UCO Bank (<code>uco.py</code>). Implemented full regex pattern sets for debit, credit, spend, balance extraction, and UTR/ref ID capture, registered with <code>ParserRegistry</code> and verified with comprehensive unit tests (<code>test_new_bank_parsers.py</code>).</li></ul></li></ul><h3 id="🚀-production-ops-demo-consolidation-ci-resilience" tabindex="-1">🚀 Production Ops, Demo Consolidation &amp; CI Resilience <a class="header-anchor" href="#🚀-production-ops-demo-consolidation-ci-resilience" aria-label="Permalink to &quot;🚀 Production Ops, Demo Consolidation &amp; CI Resilience&quot;">​</a></h3><ul><li><strong>Render.io Deployment &amp; Demo-Render-IO Retirement (<code>Infra</code>, <code>Backend</code>, <code>Docs</code>)</strong>: <ul><li>Retired obsolete <code>Demo-Render-IO</code> repository; decoupled it from all workspace CLI scripts (<code>wf.sh</code>, <code>sync.sh</code>, <code>status.sh</code>, <code>setup.sh</code>, <code>release.sh</code>) and cleanly removed it from the workspace.</li><li>Render demonstration deployment now standardizes on <code>Infra/docker/Dockerfile.demo</code> (<code>ghcr.io/wealthfam/wealthfam:demo</code>), featuring embedded pre-seeded PostgreSQL, single-port Nginx routing, and dynamic <code>$PORT</code> handling.</li><li>Resolved container startup crash on Render by eliminating redundant <code>pdfplumber</code> dependency in <code>Backend/app/modules/ingestion/statement_processor.py</code>, switching statement heuristic pre-filtering to use the native in-memory PyMuPDF engine already present in <code>Backend</code>.</li><li>Fixed Render runtime failure (<code>/usr/sbin/nginx: Operation not permitted</code>, exit status 126) by removing <code>libcap2-bin</code> and <code>setcap</code> from <code>Infra/docker/Dockerfile.demo</code>, complying with Render&#39;s <code>PR_SET_NO_NEW_PRIVS=1</code> security policy.</li></ul></li><li><strong>Unprivileged Container Port Hardening (<code>Web-App</code>, <code>Infra</code>, <code>Test-Suite</code>, <code>Docs</code>)</strong>: <ul><li>Modernized <code>Web-App/Dockerfile</code> to remove <code>libcap</code> / <code>setcap</code> and bind to unprivileged port <code>8080</code> (matching the hardened pattern in <code>Admin-Web</code>), eliminating privilege escalation requirements.</li><li>Updated <code>Infra/advanced-stack/docker-compose.yml</code> to map host port <code>80</code> to container port <code>8080</code> (<code>80:8080</code>), maintaining seamless external access while ensuring compatibility with rootless runtimes and Kubernetes <code>allowPrivilegeEscalation: false</code>.</li><li>Updated healthcheck contracts and documentation across <code>Test-Suite</code>, <code>advanced_stack.md</code>, and <code>workspace_repos.md</code>.</li></ul></li><li><strong>FastAPI OpenAPI Route Deduplication &amp; Mobile API Hygiene (<code>Backend</code>)</strong>: <ul><li>Unified <code>/heatmap</code>, <code>/heatmap/calendar</code>, and <code>/expense-groups</code> route signatures in <code>Backend/app/modules/mobile/api/router.py</code>.</li><li>Eliminated duplicate route definitions that triggered <code>UserWarning: Duplicate Operation ID</code> in FastAPI OpenAPI schema generation. Verified all 283 endpoints generate with zero schema warnings.</li></ul></li><li><strong>Automated Test-Suite Isolation &amp; Sockets Decoupling (<code>Test-Suite</code>, <code>Backend</code>)</strong>: <ul><li>Replaced live <code>SessionLocal</code> Postgres connections in <code>test_attention_summary.py</code> with isolated in-memory SQLite (<code>sqlite:///:memory:</code>) using <code>@compiles(JSONB, &quot;sqlite&quot;)</code>.</li><li>Mocked <code>NAVService.get_nav_history</code> in <code>test_mf_intelligence.py</code> test client, preventing unmocked <code>MarketSessionLocal</code> Postgres socket connection errors.</li><li>Added <code>get_current_user_or_ticket</code> dependency override in <code>test_vault_rbac.py</code> and handled transient network resets in <code>conftest.py</code>.</li><li>Unified test runner (<code>./wf.sh test</code>) passes with 100% clean execution across Python compilation, 151 pytest tests, Web-App build, and Admin-Web build.</li></ul></li></ul><h3 id="📈-mutual-fund-intelligence-suite" tabindex="-1">📈 Mutual Fund Intelligence Suite <a class="header-anchor" href="#📈-mutual-fund-intelligence-suite" aria-label="Permalink to &quot;📈 Mutual Fund Intelligence Suite&quot;">​</a></h3><ul><li><strong>Tax Optimization &amp; Tax-Loss Harvesting Engine (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Implemented strict FIFO tax lot decomposition engine (<code>MFTaxService</code>) tracking remaining buy lots, cost basis, holding days, and unrealized gains across equity vs. debt funds.</li><li>Integrated Indian Finance Act 2024 compliance with real-time ₹1.25L annual LTCG exemption tracking and headroom calculation (<code>remaining_exemption_headroom</code>).</li><li>Added automated tax-loss and tax-exemption harvesting suggestions with projected tax savings and near-LTCG qualification alerts (315-365 days).</li><li>Built interactive <code>TaxOptimizationCard.vue</code> on Web with progress meter, lot breakdowns, and 1-click harvesting suggestions; added mobile progress widget in <code>mutual_funds_screen.dart</code>.</li></ul></li><li><strong>Portfolio Overlap &amp; Entity Concentration Risk Engine (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Created <code>mutual_fund_constituents</code> table and curated holdings profiles for major Indian fund houses (Large Cap, Flexi Cap, Mid Cap, Small Cap) with category archetype fallbacks.</li><li>Built pairwise overlap matrix calculation $\\sum \\min(w_A, w_B)$ identifying common stock holdings and redundant fund pairings.</li><li>Implemented aggregate equity concentration tracking across all schemes, generating critical (&gt;15%) and warning (&gt;10%) alerts alongside a portfolio diversity score (0-100).</li><li>Built <code>PortfolioOverlapCard.vue</code> with pairwise matrix and top 15 company holdings.</li></ul></li><li><strong>Sectoral Heatmap &amp; Market Cap Exposure (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Engineered exposure aggregator across 12 standard economic sectors (<code>MFSectoralService</code>) with color-coded branding and interactive drills into contributing funds and constituent stocks.</li><li>Added market capitalization breakdown (Large Cap, Mid Cap, Small Cap, Cash &amp; Debt).</li><li>Built <code>SectorHeatmapCard.vue</code> with segmented cap bar and interactive sector cards.</li></ul></li><li><strong>SIP Intelligence, Cash-Flow Matching &amp; Step-Up Compounding (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Implemented automated recurring order clustering (<code>MFSipService</code>) identifying active monthly SIPs and execution dates into <code>mutual_fund_sips</code> table.</li><li>Generated dynamic 30-day chronological calendar matching upcoming SIP debits against primary liquid bank account balances (<code>Account.balance</code>), flagging liquidity shortfall and bounce risks.</li><li>Built 5/10/15-year compounding annual step-up simulator (0%, 5%, 10%, 15%) projecting wealth differentials over flat investments.</li><li>Built <code>SipIntelligenceCard.vue</code> and integrated mobile liquidity badges.</li></ul></li><li><strong>Peer Comparison, Category Benchmarking &amp; Alpha/Beta Risk Analytics (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>, <code>Test-Suite</code>)</strong>: <ul><li>Engineered time-series quantitative engine (<code>MFPeerAnalyticsService</code>) computing Beta ($\\beta$), Jensen&#39;s Alpha ($\\alpha$), Sharpe ratio, and annualized volatility against category TRI benchmarks.</li><li>Evaluated fund-by-fund quartile rankings (Quartile 1 Top 25%, Outperformer, Stable Alpha, Lagging).</li><li>Structured AI Advisor markdown adhering to <code>PRACTICES.md</code> Section 16.1 with mandatory symbols (<code>🎯 Executive Summary</code>, <code>⚖️ Recommended Moves / Actions</code>, <code>📈 Opportunities / Alpha</code>, <code>🛡️ Risk Guardrails / Warnings</code>).</li><li>Built <code>PeerComparisonCard.vue</code> with risk KPI tiles, ranking tables, and Glassmorphic advisory insights.</li></ul></li></ul><h3 id="🔒-core-production-security-resilience-hardening" tabindex="-1">🔒 Core Production Security &amp; Resilience Hardening <a class="header-anchor" href="#🔒-core-production-security-resilience-hardening" aria-label="Permalink to &quot;🔒 Core Production Security &amp; Resilience Hardening&quot;">​</a></h3><ul><li><strong>Eliminate URL-Parameter Tokens (<code>Backend</code>, <code>Admin-Backend</code>, <code>Web-App</code>, <code>Admin-Web</code>)</strong>: <ul><li>Removed <code>token_query</code> JWT parameter from <code>Backend/app/modules/auth/dependencies.py</code> and <code>Admin-Backend/app/main.py</code>.</li><li>Introduced thread-safe, single-use ticket service (<code>wft_...</code>, 60s TTL) with <code>POST /ticket</code> endpoint and <code>get_current_user_or_ticket</code> dependency for secure Vault <code>/download</code>, <code>/view</code>, and <code>/thumbnail</code> endpoints.</li><li>Updated <code>Web-App</code> client (<code>client.ts</code>, <code>Vault.vue</code>, <code>VaultItemCard.vue</code>, <code>Statements.vue</code>) to use authenticated blob loading with ObjectURL lifecycle management and one-time tickets.</li><li>Upgraded WebSocket streaming in <code>Web-App</code> (<code>useWebSockets.ts</code>) and <code>Admin-Web</code> (<code>LogsView.vue</code>) to use the standard <code>Sec-WebSocket-Protocol</code> header handshake (<code>wealthfam-auth</code> and <code>wealthfam-admin-auth</code>) and Bearer Authorization headers instead of URL query parameters.</li></ul></li><li><strong>Non-Root Docker Services Across All Images (<code>Infra</code>, <code>Backend</code>, <code>Parser</code>, <code>Admin-Backend</code>, <code>Web-App</code>, <code>Admin-Web</code>, <code>Demo-Render-IO</code>)</strong>: <ul><li>Created dedicated unprivileged user <code>appuser:appgroup</code> (UID/GID 10001) in microservices (<code>Backend/Dockerfile</code>, <code>Parser/Dockerfile</code>, <code>Admin-Backend/Dockerfile</code>, <code>Infra/docker/Dockerfile</code>, <code>Demo-Render-IO/Dockerfile</code>).</li><li>Configured UI frontend images (<code>Web-App/Dockerfile</code>, <code>Admin-Web/Dockerfile</code>) to execute under unprivileged <code>nginx</code> user (<code>USER nginx</code>) with <code>/tmp/nginx.pid</code> and <code>/tmp/*_temp</code> caches, granting <code>cap_net_bind_service</code> where binding port 80.</li><li>Configured <code>Infra/docker/Dockerfile.demo</code> with embedded PostgreSQL to run entirely unprivileged under <code>USER postgres</code> with <code>setcap</code> on Nginx and removed root <code>su -</code> invocations.</li><li>Explicitly set <code>user: &quot;10001:10001&quot;</code> in <code>docker-compose.yml</code> configurations and updated volume permission workflows.</li></ul></li><li><strong>Automated Backup Strategy (<code>Infra</code>, <code>Backend</code>, <code>Test-Suite</code>)</strong>: <ul><li>Implemented production CLI backup routine (<code>Infra/scripts/maintenance/backup.py</code>) supporting compressed PostgreSQL (<code>pg_dump -Fc</code>), DuckDB (<code>CHECKPOINT</code> + copy), <code>/data/vault</code>, <code>/data/logos</code>, SHA-256 integrity manifest generation (<code>manifest.json</code>), and automated retention rotation.</li><li>Implemented verification and restore CLI routine (<code>Infra/scripts/maintenance/restore.py</code>) with manifest checksum validation, dry-run mode, and directory extraction.</li><li>Scheduled daily automated backups in <code>Backend/app/core/scheduler.py</code> via APScheduler (<code>03:30 UTC</code>), configurable via <code>BACKUP_ENABLED</code>.</li><li>Created automated backup/restore verification test suite (<code>Test-Suite/modules/infra/test_backup_restore.py</code>).</li></ul></li></ul><h3 id="🔔-unified-attention-approvals-ux" tabindex="-1">🔔 Unified Attention &amp; Approvals UX <a class="header-anchor" href="#🔔-unified-attention-approvals-ux" aria-label="Permalink to &quot;🔔 Unified Attention &amp; Approvals UX&quot;">​</a></h3><ul><li><strong>Global &quot;Needs Attention&quot; / Action Required Hub (<code>Backend</code>, <code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: <ul><li>Built a unified top-bar &quot;Needs Attention&quot; amber action badge (<code>⚡ {N} Actions</code>) and 2-tab center (<em>Action Required</em> vs. <em>Activity Notifications</em>) in Web-App with animated ping pulse and one-click navigation.</li><li>Added dedicated &quot;Pending Actions&quot; row on Mobile-App <code>DashboardScreen</code> between Unified Hero Card and Daily Spending Bar Chart with dynamic viewport budgeting (<code>+46.0</code>) and auto-collapsing.</li><li>Single-pass aggregated summary service (<code>AttentionService</code>) with sub-15ms queries exposed via <code>GET /api/v1/finance/statements/attention-summary</code> and <code>GET /api/v1/mobile/attention-summary</code>.</li><li>Comprehensive multi-domain coverage: Unattended/Pending/Failed Statements, Transaction Triage, Suggested Transfers, Credit Card Due/Overdue, Budget Breaches, Loan EMIs, Recurring Suggestions, Account Low Balance &amp; Overdraft, and Stale CAS Freshness.</li><li>Full child account shielding (<code>UserRole.CHILD</code> forced to 0 for all sensitive debts/accounts).</li><li><strong>Unattended Statements &amp; User-Closed Flag (<code>is_attended</code> / <code>closed_at</code>)</strong>: Added <code>is_attended</code> and <code>closed_at</code> tracking to <code>Statement</code> model, supporting explicit attend/reopen override via <code>PATCH /statements/{id}/attend</code>, warning confirmation modals on unreconciled transactions, notice banners, status badges, and auto-resetting <code>is_attended = False</code> on reprocessing.</li></ul></li></ul><h3 id="🛠️-parser-ops-statement-engines-ingestion-hardening" tabindex="-1">🛠️ Parser Ops, Statement Engines &amp; Ingestion Hardening <a class="header-anchor" href="#🛠️-parser-ops-statement-engines-ingestion-hardening" aria-label="Permalink to &quot;🛠️ Parser Ops, Statement Engines &amp; Ingestion Hardening&quot;">​</a></h3><ul><li><strong>Upgrade <code>casparser</code> from <code>&lt;1.0</code> to <code>1.x</code> (<code>Parser</code> &amp; <code>Infra</code>)</strong>: <ul><li>Upgraded <code>casparser</code> pin from <code>0.8.1</code> to <code>1.4.1+</code> with <code>casparser-isin</code> leveraging native <code>pypdfium2</code> backend.</li><li>Completely purged legacy <code>0.8.x</code> monkey-patching of <code>casparser.process</code> in <code>Parser/core/utils.py</code> (<code>patch_casparser</code>), <code>Test-Suite</code>, and <code>Demo-Render-IO</code>. Configured native CAMS, KFintech, CDSL, and NSDL parsers with safe decimal wrappers and fallback CDSL detection.</li><li>Removed deprecated <code>force_pdfminer: True</code> across <code>Parser/parsers/cas/cas_parser.py</code> and <code>Demo-Render-IO</code>.</li><li>Updated dependency pin in <code>Parser/requirements.txt</code> and <code>Infra/docker/Dockerfile</code> (<code>casparser&gt;=1.4.1,&lt;2.0</code>).</li><li>Verified zero regressions across CAS PDF parsing, AMC SOA fail-safe delegation, and password auto-trialing (47/47 parser tests, 14/14 storage vault hardening tests, and end-to-end API tests passing).</li></ul></li><li><strong>Bank of Baroda Statement Parser &amp; Ingestion Diagnostics (<code>Parser</code>, <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li>Built dedicated column-slicing parser for Bank of Baroda bank statements (<code>Parser/parsers/statement/parsers/bob.py</code> &amp; <code>Demo-Render-IO</code>) with multi-line narration aggregator, UPI 12-digit RRN extraction (<code>ref_id</code>), auto-masking (<code>0306</code>), and non-transaction row filtering.</li><li>Added unit test suite in <code>Test-Suite/modules/parser/test_bob_statement_parser.py</code> (both text extraction and live OCR PDF pipeline passing).</li><li>Fixed uninitialized <code>logs</code> reference in <code>Parser/api/ingestion.py</code> and sanitized raw <code>Parser failed: []</code> messages across <code>Backend</code>, <code>Web-App</code>, and <code>Mobile-App</code> to provide clear, actionable guidance for non-statement attachments (Demat registers, tax challans, TDS tutorials).</li><li>Implemented default hiding of attended statements (<code>is_attended=false</code>) with user toggle switch (<code>Show Attended</code> ↔ <code>Showing Attended</code>) and auto-advance across Web and Mobile.</li></ul></li><li><strong>CORS Normalization &amp; MultiFernet Secret Key Rotation (<code>Backend</code>, <code>Parser</code>, <code>Admin-Backend</code>)</strong>: <ul><li>Normalized CORS origin parsing across microservices with trailing slash and whitespace stripping.</li><li>Implemented <code>CryptoUtils</code> MultiFernet key rotation (<code>PREVIOUS_SECRET_KEYS</code>) with automatic fallback to legacy keys to protect at-rest credentials.</li><li>Sanitized 422 RequestValidationError logging to eliminate PII/credential echoing, and added non-blocking default key security advisories at startup.</li></ul></li><li><strong>Indian Mutual Fund Individual AMC Statement (SOA) Support, Multi-Row Layouts &amp; Folio Deduplication (<code>Parser</code> &amp; <code>Backend</code>)</strong>: <ul><li>Built <code>AmcSoaParser</code> master dispatcher supporting three specialized RTA statement layout engines: <ul><li><code>KfintechSingleRowSoaParser</code>: Single-row KFintech statements (Nippon India MF, Axis MF, legacy KFintech) with inline stamp duty parentheticals.</li><li><code>KfintechMultiRowSoaParser</code>: Modern 3-row KFintech statement layouts (Quant MF, Groww MF, modern KFintech) filtering out intermediate <code>Gross Purchase</code> and <code>Stamp Duty / STT</code> rows while extracting exact Net execution amounts, units, and NAVs via visual block stream analysis and mathematical metric resolution ($\\text{Amount} \\approx \\text{Units} \\times \\text{NAV}$).</li><li><code>CamsSoaParser</code>: CAMS-serviced AMCs (HDFC MF, ICICI Prudential, SBI MF, Kotak Mahindra, DSP, etc.).</li></ul></li><li>Authenticated encrypted PDFs inside <code>AmcSoaParser.can_handle(file_bytes, password)</code> using PAN credentials before page header inspection, eliminating <code>fitz.FileDataError</code> decryption exceptions.</li><li>Automated fail-safe delegation from <code>casparser</code> when standard CAS headers are absent (<code>investor_info</code> validation failure).</li><li>Normalized mutual fund folios (<code>_normalize_folio</code>) to strip RTA check-digit suffixes (<code>/ 0</code>, <code>/ 00</code>), resolving false-negative duplicate detection across CAS and direct AMC statements.</li><li>Tenant-level multi-member deduplication and intelligent target user resolution based on existing folio ownership and statement context.</li><li>Comprehensive test coverage (<code>test_amc_soa_parser.py</code>, 7/7 tests passing) across unencrypted, encrypted with PAN, Groww 4-transaction and Quant 8-transaction fixtures.</li></ul></li><li><strong>HDFC Modern Credit Card Parser &amp; Card Mask Prioritization (<code>Parser</code>)</strong>: <ul><li>Unified modern HDFC credit card statements (Swiggy, Tata Neu, Millennia) into <code>hdfc_credit_card.py</code>.</li><li>Hardened card mask extraction in <code>statement_parser.py</code> to prioritize <code>Credit Card No.</code> patterns before evaluating internal billing <code>Alternate Account Number</code> fields, preventing account mask mismatches (<code>7115</code> vs <code>7119</code>).</li></ul></li><li><strong>Batch Email Pipeline Hardening (<code>Parser/core/batch_pipeline.py</code>)</strong>: <ul><li>Guard against <code>None</code> values for <code>subject</code> and <code>sender</code> (<code>item.get(&quot;subject&quot;) or &quot;&quot;</code>, <code>item.get(&quot;sender&quot;) or &quot;&quot;</code>) since <code>BatchItem</code> fields default to <code>None</code> and are inserted into <code>items_dicts</code> in <code>Parser/api/batch_ingestion.py</code>.</li><li>Pass <code>sender</code> to <code>EmailParser.can_handle(...)</code> (for parsers accepting optional <code>sender</code>, e.g. <code>IdbiEmailParser</code>) and forward <code>received_at</code> as <code>date_hint</code> to <code>p.parse(...)</code>.</li></ul></li><li><strong>CAS Routing, Retry Loop &amp; 400 Error Visibility (<code>Backend</code> &amp; <code>Parser</code>)</strong>: <ul><li>Tightened <code>MutualFundCasHandler.can_handle()</code> in <code>Backend/app/modules/ingestion/handlers/cas_handler.py</code> (word-bounded <code>r&#39;\\bcas\\b&#39;</code>, narrowed <code>r&#39;consolidated&#39;</code> and depository sender matching so non-CAS PDFs aren&#39;t misrouted to <code>/v1/ingest/cas</code>).</li><li>Prevented <code>StatementProcessor.sync_statements()</code> (<code>Backend/app/modules/ingestion/statement_processor.py</code>) from repeatedly retrying already-<code>FAILED</code> PDFs on every 3-hour automated sync cycle while keeping manual <code>/reprocess</code> retries enabled.</li><li>Surfaced CAS 400 errors clearly across <code>Parser/api/ingestion.py</code> and <code>Backend/app/modules/ingestion/parser_service.py</code>.</li></ul></li><li><strong>True Single-Pass Email &amp; Attachment Routing (<code>Backend</code>)</strong>: <ul><li>Consolidated the two-pass IMAP flow (<code>EmailSyncService.sync_emails</code> + <code>StatementProcessor.sync_statements</code> in <code>Backend/app/core/scheduler.py</code>) into one IMAP pass and removed dead <code>CASParser.scan_cas_emails</code>.</li></ul></li><li><strong>Slice Bank Parser Hardening (<code>Parser/parsers/statement/parsers/slice.py</code>)</strong>: <ul><li>Fixed <code>txn_header_regex</code> to support negative amounts (<code>-₹...</code>), multi-line description wrapping across 2-3 lines, and alphanumeric/hyphen/slash UPI reference IDs.</li><li>Switched credit/debit determination to amount sign (resolving misclassification of <code>UPI-Reversal</code> transactions as debits).</li><li>Hardened account mask extraction to prioritize <code>A/C number</code> over <code>Customer ID</code> on first page metadata, ensuring correct 4-digit mask extraction.</li></ul></li><li><strong>422 Validation Error Log Hygiene (<code>Backend</code>)</strong>: Stopped logging and echoing raw <code>exc.body</code> in <code>validation_exception_handler</code> (<code>Backend/app/main.py</code>) so sensitive payloads/credentials cannot leak into logs or responses.</li></ul><h3 id="🛡️-admin-stack-integration-stateless-parser-engine" tabindex="-1">🛡️ Admin Stack Integration &amp; Stateless Parser Engine <a class="header-anchor" href="#🛡️-admin-stack-integration-stateless-parser-engine" aria-label="Permalink to &quot;🛡️ Admin Stack Integration &amp; Stateless Parser Engine&quot;">​</a></h3><ul><li><strong>Parser Stateless Code-Driven Refactor &amp; Comprehensive Admin Testing Studio (<code>Parser</code>, <code>Backend</code>, <code>Admin-Backend</code>, <code>Admin-Web</code>)</strong>: <ul><li><strong>100% Stateless &amp; Code-Driven Engine</strong>: Refactored <code>Parser</code> to run strictly via compiled Python bank and statement parsers (&lt; 0.5ms execution). Replaced DuckDB duplicate checks with an in-memory 5-minute thread-safe LRU submission cache (<code>RecentSubmissionCache</code>).</li><li><strong>Zero Financial PII at Rest &amp; Zero Lock Contention</strong>: Dropped runtime writes to <code>request_logs</code>. Retired hourly background cleanup scheduler (<code>Parser/core/scheduler.py</code> and <code>Parser/main.py</code>), completely eliminating DuckDB file-lock contention during parallel batch parsing.</li><li><strong>Preserved API Contracts &amp; Zero-State Responses</strong>: All ingestion endpoints (<code>/sms</code>, <code>/email</code>, <code>/file</code>, <code>/cas</code>, <code>/statement</code>, <code>/test</code>) retain their exact schemas; <code>/v1/stats</code> returns clean statistics without hitting DuckDB.</li><li><strong>Retired Obsolete Endpoints &amp; Dynamic DB Pattern Injection</strong>: Deleted <code>Parser/api/patterns.py</code> (282 lines of dead DuckDB CRUD), removed <code>app.include_router(patterns.router)</code> from <code>main.py</code>, removed proxy <code>/patterns</code> routes in <code>Admin-Backend/app/api/parsers.py</code>, and removed dead client methods in <code>Admin-Web</code>.</li><li><strong>Zero Database Dependencies &amp; Complete DuckDB/SQLAlchemy Severance</strong>: Completely deleted <code>Parser/db/</code> (<code>database.py</code> and <code>models.py</code>), removed <code>duckdb</code>, <code>duckdb-engine</code>, and <code>sqlalchemy</code> from <code>Parser/requirements.txt</code>. Refactored <code>/health</code> readiness probes to in-memory native parser registry validation and updated <code>test_healthchecks.py</code>.</li><li><strong>Two-Tier Deduplication Alignment</strong>: Documented decoupled deduplication architecture: Tier 1 fast-path in-memory LRU idempotency guard in <code>Parser</code> + Tier 2 authoritative cross-source deduplication in <code>Backend</code> via <code>TransactionDeduplicator</code> against PostgreSQL.</li><li><strong>Admin Testing Studio for SMS, Email &amp; PDFs</strong>: Enhanced <code>Admin-Backend</code> (<code>POST /v1/parsers/sandbox/pdf</code> with live statement parser forwarding) and <code>Admin-Web</code> (<code>ParsersView.vue</code>) with a full testing studio: side-by-side evaluation of built-in Python parsers, live microservice responses, custom regex prototyping, and PDF statement structure &amp; transaction preview.</li><li><strong>Pure Code-First Philosophy &amp; Template UI Deprecation</strong>: Cleaned up legacy declarative template modals and CRUD workflows in <code>Admin-Web</code>, replacing &quot;Build Template&quot; with 1-click &quot;Test in Studio&quot;.</li><li><strong>Consented Training Inbox &amp; Format-Preserving Anonymizer</strong>: Displays user-submitted unrecognized alerts with automated deduplication counters (<code>50x</code>), two-tier redaction, and 1-click promotion to the Testing Studio.</li><li><strong>Comprehensive Test Suite</strong>: Added <code>Test-Suite/modules/admin/test_parser_studio_and_stateless.py</code> covering stateless extraction, duplicate submission guards, non-financial filtering, and Admin Studio text/PDF testing.</li></ul></li></ul><h3 id="📱-mobile-data-entry-features" tabindex="-1">📱 Mobile Data Entry &amp; Features <a class="header-anchor" href="#📱-mobile-data-entry-features" aria-label="Permalink to &quot;📱 Mobile Data Entry &amp; Features&quot;">​</a></h3><ul><li><strong>Mobile Goals Creation</strong>: Implemented <code>_showAddGoalDialog(context)</code> modal creation workflow in <code>Mobile-App/lib/modules/home/screens/goals_screen.dart</code> with target amounts and timelines.</li><li><strong>Mobile Expense Groups Creation</strong>: Implemented <code>_showGroupFormSheet(context)</code> in <code>Mobile-App/lib/modules/home/screens/expense_groups_screen.dart</code> with color tagging, member assignment, budget caps, and dynamic date ranges.</li></ul><h3 id="🛠️-ingestion-operations-tooling" tabindex="-1">🛠️ Ingestion &amp; Operations Tooling <a class="header-anchor" href="#🛠️-ingestion-operations-tooling" aria-label="Permalink to &quot;🛠️ Ingestion &amp; Operations Tooling&quot;">​</a></h3><ul><li><strong>Dedicated Admin Console &amp; Parser Studio (<code>Admin-Backend</code> &amp; <code>Admin-Web</code>)</strong>: Built the port-isolated operations portal (<code>:8002</code> / <code>:5174</code> / <code>:8080</code>) featuring built-in bank parser introspection, declarative parser template studio, sandbox testing, training inbox, brand logo/regex manager, endpoint observatory, and DuckDB telemetry.</li><li><strong>Consumer Shielding &amp; Unified Ingestions Hub (<code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: Removed <code>ParserSettings.vue</code> and all <code>/parser</code> client proxies/references from consumer apps; replaced them with unified <strong>Settings → Ingestions</strong> (<code>IngestionsSettings.vue</code>) and Mobile <strong>Ingestions</strong> (<code>ingestion_activity_tab.dart</code>).</li><li><strong>Pre-Ingestion Ignore Rules &amp; &quot;Allow Later&quot; Unblocking</strong>: Added <code>IngestionService.check_ignore_rules()</code> prior to extraction plus <code>GET/POST/DELETE /api/v1/ingestion/ignore-rules</code> (and <code>/api/v1/mobile/ingestion/ignore-rules</code>).</li><li><strong>Email Financial Classifier &amp; Parser Hardening (<code>Parser</code>)</strong>: Fixed word-bounded verb/currency matching and strict <code>EMAIL</code> rules in <code>FinancialClassifier.is_financial()</code>, removed loose fallback fabrication in <code>SbiEmailParser</code> and <code>GenericEmailParser</code>, and fixed <code>PnbEmailParser</code>/<code>IdbiEmailParser</code> method signatures.</li><li><strong>Backend-Native PostgreSQL Merchant Aliases</strong>: Migrated <code>MerchantAlias</code> (<code>merchant_aliases</code>) to Backend PostgreSQL, applied centrally across SMS, Email, CSV, PDF Statements, and <code>bulk_rename</code>, and exposed under <strong>Categories &amp; Rules → Merchant Aliases</strong> (<code>MerchantAliasesPanel.vue</code>).</li><li><strong>Config-Driven Anonymized Alert Reporting (<code>ADMIN_SERVICE_URL</code>)</strong>: Added config-driven <code>ADMIN_SERVICE_URL</code> / <code>ADMIN_API_V1_URL</code> across <code>Backend</code>, <code>.env</code>, and <code>Infra</code>, proxying <code>/api/v1/ingestion/anonymize-preview</code> and <code>/api/v1/ingestion/report-unrecognized</code> through <code>Backend</code> (<code>:8000</code>) with local regex masking fallback.</li><li><strong>Admin Log Stream WebSocket Auth Enforcement (<code>Admin-Backend</code> &amp; <code>Admin-Web</code>)</strong>: Enforced valid admin JWT verification on <code>@app.websocket(&quot;/v1/logs/stream&quot;)</code> in <code>Admin-Backend/app/main.py</code>, closing unauthenticated/empty/tampered connections with code 4008, added token presence checks in <code>Admin-Web/src/views/LogsView.vue</code>, and added comprehensive connection tests in <code>test_admin_stack.py</code>.</li><li><strong>Brand Logo &amp; Regex Integration (<code>Backend</code>, <code>Admin-App</code>, <code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: <ul><li><strong>Tenant-Independent Model &amp; Clean Slate</strong>: Created PostgreSQL <code>brand_logos</code> model and migration (<code>e6f7a8b9c0d1</code>) without tenant isolation starting with zero default seed data. Removed legacy DuckDB seeders and deleted legacy dummy SVG assets.</li><li><strong>Universal Image Processing &amp; Normalization</strong>: Implemented Pillow-powered conversion in <code>BrandService</code> accepting any image format and normalizing to 256x256 WebP RGBA while preserving valid SVGs and dynamically generating monogram SVGs/WebPs.</li><li><strong>Multiline Regex Support &amp; Hoisting</strong>: Added support for multiline regex patterns per brand logo, combining patterns with safe hoisting of root <code>(?i)</code> flags.</li><li><strong>Centralized Auth &amp; Administrative Endpoints</strong>: Centralized <code>require_admin_or_service_auth</code> in <code>backend.app.modules.auth.dependencies</code>; exposed public <code>/api/v1/brands/catalog</code> and <code>/api/v1/brands/files/{filename}</code>, alongside full administrative CRUD and ZIP import/export.</li><li><strong>Admin App Full CRUD &amp; Disable Toggle</strong>: Updated <code>Admin-Backend/app/api/brands.py</code> and <code>Admin-Web/src/views/BrandsView.vue</code> with universal image upload, 1-click active/disabled toggle switch, and status badges.</li><li><strong>Dynamic Client-Side Regex Matching &amp; Category Fallback (<code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: Created <code>useBrandsStore</code> &amp; <code>BrandIcon.vue</code> on Web and <code>BrandService</code> &amp; <code>BrandAvatar</code> on Mobile.</li><li><strong>Verification &amp; Test Coverage</strong>: Added <code>Test-Suite/modules/admin/test_brands_integration.py</code> (7/7 passed).</li></ul></li><li><strong>Unified Anonymous Telemetry &amp; Log Producers (<code>Backend</code>, <code>Parser</code>, <code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>: <ul><li><strong><code>Backend</code> &amp; <code>Parser</code> Telemetry Middleware &amp; Log Shipper</strong>: Attached <code>TelemetryMiddleware</code> and <code>AsyncHttpLogHandler</code> backed by non-blocking <code>asyncio.Queue</code> background batching to <code>{ADMIN_SERVICE_URL}/v1/telemetry/ingest</code> and <code>/logs</code>. Added <code>record_parser_event</code> in <code>Parser</code>&#39;s <code>IngestionPipeline</code>.</li><li><strong><code>Mobile-App</code> (Flutter) Telemetry Service &amp; Backend Ingress Proxy</strong>: Created <code>TelemetryService</code> with offline queuing in <code>SharedPreferences</code> and <code>POST /api/v1/telemetry/ingest</code> proxying on <code>Backend</code>.</li><li><strong><code>Web-App</code> Client Telemetry, Onboarding Consent &amp; Settings Controls</strong>: Added <code>/telemetry</code> proxy, client telemetry with <code>navigator.sendBeacon</code>, onboarding consent in <code>Register.vue</code>, and 1-click toggle switches in Web &amp; Mobile settings.</li><li><strong>Verification &amp; Test Coverage</strong>: Added <code>Test-Suite/modules/admin/test_telemetry_producers.py</code> (6/6 passed).</li></ul></li></ul><h3 id="📋-pluggable-statement-financial-document-engine" tabindex="-1">📋 Pluggable Statement &amp; Financial Document Engine <a class="header-anchor" href="#📋-pluggable-statement-financial-document-engine" aria-label="Permalink to &quot;📋 Pluggable Statement &amp; Financial Document Engine&quot;">​</a></h3><ul><li><strong>Statement-Level Full CRUD &amp; Statement Ignore Rules (<code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code>)</strong>: <ul><li><strong>Statement CRUD (<code>GET/{id}</code>, Status/Type Filters, <code>PATCH</code>, Single &amp; Bulk Delete)</strong>: Added <code>status</code> &amp; <code>statement_type</code> filters, expanded <code>PATCH</code>, single delete with optional <code>delete_vault_file</code> &amp; <code>create_ignore_rule</code>, and <code>POST /finance/statements/bulk-delete</code>.</li><li><strong>Statement Ignore Rules (<code>source=&quot;STATEMENT&quot;</code>) &amp; UI Manager</strong>: Extended <code>SpamFilter</code> ignore rules to <code>STATEMENT</code>, enforced pre-vault MIME checks, added <code>POST /finance/statements/{id}/ignore</code>, and added inline <strong>Ignored Rules</strong> manager modal in <code>Statements.vue</code>.</li></ul></li><li><strong>Unified Email &amp; Document Ingestion Pipeline</strong>: <ul><li><strong>Unified Statement IMAP Sweep</strong>: Consolidated bank statements, credit card bills, and eCAS statements under <code>StatementProcessor</code> with rate-limit protection.</li><li><strong>Pluggable Handler Registry Pattern (<code>BaseStatementHandler</code>)</strong>: Standard interface supporting <code>BankStatementHandler</code>, <code>CreditCardStatementHandler</code>, and <code>MutualFundCasHandler</code>.</li><li><strong>Universal Password Auto-Trial Engine</strong>: Auto-try user PAN (<code>user.pan_number</code>), DOB permutations, and <code>StatementPasswordCache</code>.</li></ul></li><li><strong>Polymorphic Statements Workspace (<code>Statements.vue</code>)</strong>: <ul><li>Left Directory with domain badges (<code>🏦 Bank</code>, <code>💳 Card</code>, <code>📈 Mutual Fund CAS</code>), adaptive detail pane, and shared document viewer with embedded PDF preview and password retry modal.</li></ul></li><li><strong>Mutual Funds UI Simplification</strong>: <ul><li>Removed redundant &quot;Email Inbox&quot; scan mode from <code>ImportTab.vue</code> (retained manual PDF upload) and linked to <code>/statements</code>.</li></ul></li></ul><h3 id="🏛️-financial-instruments-domain-separation-parity" tabindex="-1">🏛️ Financial Instruments Domain Separation &amp; Parity <a class="header-anchor" href="#🏛️-financial-instruments-domain-separation-parity" aria-label="Permalink to &quot;🏛️ Financial Instruments Domain Separation &amp; Parity&quot;">​</a></h3><ul><li><strong>Credit Cards</strong>: Full lifecycle management, dynamic cycle calculation (<code>current_unbilled</code>, <code>last_statement</code>, <code>all</code>), bill payments, and utilization health.</li><li><strong>Fixed &amp; Recurring Deposits</strong>: Dedicated domain tables, quarterly compounding math, accrued interest calculation, maturity tracking, and deposit ledger with dedicated Web &amp; Mobile screens.</li><li><strong>Provident Funds (EPF/PPF/NPS)</strong>: Tripartite balance tracking (employee, employer, pension), annual interest simulation, and post-tax statutory FY deposit ceiling meter (₹1.5L cap) on Web and Mobile.</li><li><strong>Loans Enhancement</strong>: Support for lender names, account numbers, and cross-account EMI tracking.</li><li><strong>Multi-Instrument Mobile Parity</strong>: Created <code>DepositModel</code>, <code>ProvidentFundModel</code>, <code>deposits_screen.dart</code>, <code>provident_funds_screen.dart</code>, and added Credit Card destination in AppDrawer.</li></ul><h3 id="🔄-cross-account-transfers-pairing" tabindex="-1">🔄 Cross-Account Transfers &amp; Pairing <a class="header-anchor" href="#🔄-cross-account-transfers-pairing" aria-label="Permalink to &quot;🔄 Cross-Account Transfers &amp; Pairing&quot;">​</a></h3><ul><li><strong>Automated Heuristic Detection</strong>: 4-day sliding window, asymmetric tolerance (diff ≤ ₹500 or ratio ≥ 90% for discounts/fees), account mask matching, and family member detection.</li><li><strong>Double-Entry Ledger Integrity</strong>: Mutual <code>linked_transaction_id</code> pointers, automatic <code>is_transfer = True</code> and <code>exclude_from_reports = True</code> flags to prevent duplicate expense inflation.</li><li><strong>Credit Card Dues Sync</strong>: Auto-adjusted <code>total_amount_due</code> and <code>min_amount_due</code> on card payment, with safe rollback on unpair.</li><li><strong>Mobile &amp; Web Parity</strong>: Batch approval (&quot;Approve All High-Confidence Pairs&quot;), 1-click counterpart leg creation with adjustable credited amount, and unpair actions on both Web (<code>Transfers.vue</code>) and Mobile (<code>transfers_hub_screen.dart</code>).</li></ul><h3 id="📂-document-vault-attachments" tabindex="-1">📂 Document Vault &amp; Attachments <a class="header-anchor" href="#📂-document-vault-attachments" aria-label="Permalink to &quot;📂 Document Vault &amp; Attachments&quot;">​</a></h3><ul><li><strong>Production Vault Pre-Deploy Rescue &amp; Volume Cutover</strong>: Backed up ephemeral <code>/app/data/vault</code> files onto persistent <code>/data/vault</code> and deployed <code>VAULT_STORAGE_PATH=/data/vault</code> + <code>VaultService.heal_legacy_paths</code>.</li><li><strong>Vault Direct-Endpoint RBAC Enforcement (<code>Backend</code>)</strong>: Centralized access control in <code>VaultService.can_read_document</code> and <code>can_modify_document</code>, enforced <code>is_shared</code>, <code>owner_id</code>, and <code>UserRole.CHILD</code> restrictions across all direct metadata, download, view, thumbnail, and version routes, and protected upload collision handling.</li><li><strong>Vault Statement Storage &amp; Reprocess Hardening (<code>Backend</code>, <code>Infra</code>, <code>Parser</code> &amp; <code>Web-App</code>)</strong>: Persistent <code>VAULT_STORAGE_PATH=/data/vault</code>, resilient path resolution &amp; startup self-healing, atomic <code>ensure_unlocked_pdf</code>, lazy thumbnail backfill, and hardened <code>POST /statements/{id}/reprocess</code> with SHA-256 version deduplication.</li><li><strong>Document Vault Core Engine</strong>: Secure backend vault router and service with multi-format storage, folder nesting, and transaction linking.</li><li><strong>Hierarchical Breadcrumbs &amp; Bulk Management</strong>: Nested folder navigation trail and multi-select batch deletion workflows in <code>Web-App/src/views/Vault.vue</code>.</li><li><strong>Mobile Content Previews</strong>: Seamless previewing of PDFs, receipts, and statement files via <code>open_filex</code> across mobile screens.</li></ul><h3 id="⚙️-core-resilience-background-services" tabindex="-1">⚙️ Core Resilience &amp; Background Services <a class="header-anchor" href="#⚙️-core-resilience-background-services" aria-label="Permalink to &quot;⚙️ Core Resilience &amp; Background Services&quot;">​</a></h3><ul><li><strong>Monolith Process Self-Healing (<code>Infra/orchestration/run_backend.py</code> &amp; <code>Test-Suite</code>)</strong>: Active <code>SupervisedWorker</code> supervisor loop with crash detection, exponential backoff, stability window decay, quarantine thresholds, and clean signal termination (<code>test_orchestrator_self_healing.py</code>, 5/5 passing).</li><li><strong>Data Envelope Synchronization (<code>Backend</code>)</strong>: Audited all finance routers against <code>PRACTICES.md</code> Section 2 confirming paginated resources return <code>{&quot;data&quot;: [...], &quot;total&quot;: N}</code> and bounded collections return direct arrays <code>[...]</code>.</li><li><strong>Multi-Service Health Monitoring (<code>Backend</code>, <code>Parser</code>, <code>Admin-Backend</code> &amp; <code>Infra</code>)</strong>: Added <code>/health</code> and <code>/health/live</code> endpoints, Dockerfile <code>HEALTHCHECK</code>s, 7-service monolith <code>healthcheck.sh</code>, <code>service_healthy</code> dependencies, and <code>GET /health?deep=true</code>.</li><li><strong>Unified <code>/data</code> Path &amp; Storage Consistency (<code>Backend</code>, <code>Parser</code>, <code>Admin-Backend</code> &amp; <code>Infra</code>)</strong>: Aligned <code>/data/{vault,logos}</code> path resolution across services, OSes, and Docker/orchestration scripts.</li><li><strong>Foreground Service Reliability</strong>: Hardened background SMS task handling for Android 14+ with offline retry queues (<code>sms_offline_queue</code>), non-intrusive GPS polling, and retry mechanisms (<code>foreground_task_handler.dart</code>).</li><li><strong>Client-Side Data Caching</strong>: Implemented <code>useStorePersistence</code> composable in <code>Web-App/src/utils/persistence.ts</code> caching store state in <code>localStorage</code> per member.</li></ul><h3 id="👥-family-management-intelligent-rules" tabindex="-1">👥 Family Management &amp; Intelligent Rules <a class="header-anchor" href="#👥-family-management-intelligent-rules" aria-label="Permalink to &quot;👥 Family Management &amp; Intelligent Rules&quot;">​</a></h3><ul><li><strong>Family Wealth Dashboard</strong>: High-level aggregated net worth view across all family members with top-bar member switching (<code>All Members</code> vs individual member) across Web and Mobile.</li><li><strong>Smart Rule Suggestions</strong>: Automated heuristic merchant pattern clustering in <code>CategoryService.get_rule_suggestions</code> and interactive review panel in <code>SuggestionsPanel.vue</code>.</li><li><strong>Session Revocation (&quot;Logout from all devices&quot;)</strong>: Multi-device token revocation endpoint (<code>/api/v1/auth/logout-all</code>) with UI controls in <code>DevicesSettings.vue</code>.</li></ul><h3 id="🧪-test-infrastructure" tabindex="-1">🧪 Test Infrastructure <a class="header-anchor" href="#🧪-test-infrastructure" aria-label="Permalink to &quot;🧪 Test Infrastructure&quot;">​</a></h3><ul><li><strong>Pytest Backend &amp; Admin Stack Test Suite</strong>: Established test suite in <code>Test-Suite/modules/</code> covering Auth, RBAC, Finance, Ingestion, Admin Stack, and Parser APIs.</li><li><strong>Flutter Mobile Test Suite</strong>: 57/57 tests passing across accounts, models, transactions, cache, and connectivity.</li><li><strong>Web-App Lint</strong>: 0 TypeScript or template compile errors (<code>vue-tsc --noEmit</code>).</li></ul><h3 id="🏗️-architecture-decoupling" tabindex="-1">🏗️ Architecture &amp; Decoupling <a class="header-anchor" href="#🏗️-architecture-decoupling" aria-label="Permalink to &quot;🏗️ Architecture &amp; Decoupling&quot;">​</a></h3><ul><li><strong>Modular Sub-Components</strong>: Extracted monolithic <code>Transactions.vue</code> into specialized sub-views in <code>@/views/transactions/</code> (List, Analytics, Triage, Heatmap).</li><li><strong>Mutual Fund Auto-Sync</strong>: Background sync status indicators, Top Bar manual &quot;Refresh All&quot;, and real-time NAV refresh.</li><li><strong>Balance Calculation &amp; Maintenance</strong>: Fixed anchor date boundary discrepancies (<code>&gt;=</code>), corrected liability calculation in historical analytics, and added account balance recalculation utilities.</li><li><strong>Enterprise Decoupling</strong>: Restored <code>AccountService</code> to pure instrument-agnostic CRUD and decoupled <code>StatementProcessor</code>.</li><li><strong>Active Expense Group Picker Filtering</strong>: Ensured only active expense groups (or currently assigned group) are visible when assigning transactions in mobile (<code>expense_group_picker_sheet.dart</code>).</li><li><strong>Mobile Transaction GPS Location Fix</strong>: Included <code>latitude</code> and <code>longitude</code> in <code>RecentTransaction</code> schema (<code>mobile/schemas.py</code>).</li><li><strong>Statement Ingestion &amp; Reconciliation Hardening</strong>: Auto-promoted <code>PendingTransaction</code> triage matches during statement import, guarded against unlinked <code>account_id = None</code>, replaced PostgreSQL-incompatible <code>keywords.like(...)</code> with <code>cast(keywords, String).ilike(...)</code>, and normalized hierarchical category suggestion paths in <code>Statements.vue</code>.</li><li><strong>Landing Page vs Ledger Metric Alignment</strong>: Added living expenses sub-metric and informative tooltips in the mobile and ledger views (<code>transactions_screen.dart</code>).</li><li><strong>Categories Rules Review Priority UX</strong>: Automatically pinned rules with active review/triage matches to the top of the Rules table (<code>RulesPanel.vue</code>).</li></ul>',70)])])}const g=o(a,[["render",i]]);export{m as __pageData,g as default};
